class_name Passives
# The passive skill tree: a web of nodes around the hero. 1 point per level.

# id: {name, desc, stats, ring, angle(deg), links}
static func nodes() -> Dictionary:
	var n := {
		"start": {"name": "Hero", "desc": "You!", "stats": {}, "ring": 0, "angle": 0, "links": []},
	}
	var ring1 := [
		["dmg1", "Bonk +1", {"dmg": 1}], ["hp1", "Heart +1", {"hearts": 1}], ["spd1", "Speed +8%", {"speed": 8}],
		["loot1", "Loot +10%", {"loot": 10}], ["crit1", "Mega bonk +5%", {"crit": 5}], ["en1", "Energy +15", {"energy": 15}],
	]
	var ring2 := [
		["dmg2", "Bonk +1", {"dmg": 1}], ["area1", "Bonk area +15%", {"area": 15}],
		["hp2", "Heart +1", {"hearts": 1}], ["regen1", "Energy per bonk +3", {"regen": 3}],
		["spd2", "Speed +8%", {"speed": 8}], ["xp1", "Experience +15%", {"xp": 15}],
		["loot2", "Loot +15%", {"loot": 15}], ["mag1", "Loot magnet +30%", {"magnet": 30}],
		["crit2", "Mega bonk +6%", {"crit": 6}], ["dmg3", "Bonk +1", {"dmg": 1}],
		["en2", "Energy +20", {"energy": 20}], ["hp3", "Heart +1", {"hearts": 1}],
	]
	var ring3 := [
		["k_slam", "GIANT SLAM", {"slam": 60, "area": 20}, "Slam is 60% bigger."],
		["k_iron", "IRON HEART", {"hearts": 3, "dmg": 1}, "+3 hearts, +1 bonk."],
		["k_zoom", "LIGHTNING FEET", {"speed": 20, "dash": 1}, "+20% speed, dash cools faster."],
		["k_nose", "TREASURE NOSE", {"loot": 40, "magnet": 50}, "+40% loot, huge magnet."],
		["k_crit", "LUCKY STRIKE", {"crit": 15, "dmg": 1}, "+15% mega bonk, +1 bonk."],
		["k_whirl", "WHIRLWIND MASTER", {"whirl": 50, "energy": 25}, "Whirl costs half energy."],
	]
	for i in range(6):
		var r1: Array = ring1[i]
		n[r1[0]] = {"name": r1[1], "desc": r1[1], "stats": r1[2], "ring": 1, "angle": i * 60.0, "links": ["start"]}
	for i in range(12):
		var r2: Array = ring2[i]
		var parent: String = ring1[int(i / 2)][0]
		n[r2[0]] = {"name": r2[1], "desc": r2[1], "stats": r2[2], "ring": 2, "angle": i * 30.0 - 15.0 + (0.0 if i % 2 == 0 else 0.0), "links": [parent]}
	for i in range(6):
		var r3: Array = ring3[i]
		n[r3[0]] = {"name": r3[1], "desc": r3[3], "stats": r3[2], "ring": 3, "angle": i * 60.0, "links": [ring2[i * 2][0], ring2[i * 2 + 1][0]], "keystone": true}
	# make links symmetric
	for id in n.keys():
		for l in n[id]["links"]:
			if not id in n[l]["links"]:
				n[l]["links"].append(id)
	return n

static func pos(node: Dictionary, radius: float = 84.0) -> Vector2:
	var r: float = node["ring"] * radius
	var a: float = deg_to_rad(node["angle"] - 90.0)
	return Vector2(cos(a) * r, sin(a) * r)

files.scripts/world.gd:
extends Node3D
class_name World
# Builds the island: terrain, water, sky, grass, trees, rocks, village, boss hill, chests.

const SIZE := 230.0
const STEP := 2.0
const WATER_Y := 0.15
const VILLAGE := Vector2(0, 8)
const BOSS_CENTER := Vector2(62, -62)
const BOSS_R := 16.0
const WINDMILL_POS := Vector2(-22, 26)

var noise := FastNoiseLite.new()
var noise2 := FastNoiseLite.new()
var noise3 := FastNoiseLite.new()
var terrain: MeshInstance3D
var terrain_body: StaticBody3D
var props_body: StaticBody3D
var grass_mm: MultiMeshInstance3D
var grass_mat: ShaderMaterial
var windmill_blades: Node3D
var clouds: Array[Node3D] = []
var islands: Array[Node3D] = []
var boss_gate_open := false
var gate_bars: Array[Node3D] = []
var chests: Array = []
var npcs := {}
var sun: DirectionalLight3D
var env: WorldEnvironment
var paths: Array = []  # arrays of Vector2 polylines
var trees: Array = []   # [pos2, radius] for spawn avoidance
var fountain_pos := Vector3(0, 1, 8)
var tree_spin: Array = []

func _ready() -> void:
	noise.seed = 1337
	noise.frequency = 0.02
	noise.fractal_octaves = 3
	noise2.seed = 42
	noise2.frequency = 0.045
	noise3.seed = 99
	noise3.frequency = 0.12
	paths = [
		[Vector2(0, 8), Vector2(-10, -6), Vector2(-24, -22), Vector2(-40, -42), Vector2(-50, -58)],
		[Vector2(0, 8), Vector2(18, 4), Vector2(36, 0), Vector2(52, 6), Vector2(68, 14)],
		[Vector2(0, 8), Vector2(10, -10), Vector2(22, -28), Vector2(40, -42), Vector2(52, -52)],
		[Vector2(0, 8), Vector2(-4, 26), Vector2(-14, 44), Vector2(-20, 60)],
	]
	build_sky()
	build_terrain()
	build_water()
	build_grass()
	build_flora()
	build_village()
	build_boss_hill()
	build_clouds()
	build_islands()
	build_chests()

# ---------------- height field ----------------
func hill_mask(x: float, z: float) -> float:
	# east hills
	var d := Vector2(x, z).distance_to(Vector2(62, -10))
	var m := 1.0 - smoothstep(14.0, 46.0, d)
	var d2 := Vector2(x, z).distance_to(Vector2(40, -36))
	m = max(m, 1.0 - smoothstep(10.0, 30.0, d2))
	return m

func plateau_mask(x: float, z: float) -> float:
	var d := Vector2(x, z).distance_to(BOSS_CENTER)
	return 1.0 - smoothstep(BOSS_R, BOSS_R + 9.0, d)

func village_mask(x: float, z: float) -> float:
	var d := Vector2(x, z).distance_to(VILLAGE)
	return 1.0 - smoothstep(16.0, 26.0, d)

func island_mask(x: float, z: float) -> float:
	# rounded square island
	var p := Vector2(abs(x), abs(z))
	var r: float = (p - Vector2(70, 70)).clamp(Vector2.ZERO, Vector2(999, 999)).length() + minf(maxf(p.x - 70, p.y - 70), 0.0)
	return 1.0 - smoothstep(14.0, 30.0, r + noise2.get_noise_2d(x * 2.0, z * 2.0) * 6.0)

func path_dist(x: float, z: float) -> float:
	var best := 1e9
	var p := Vector2(x, z)
	for pl in paths:
		for i in range(pl.size() - 1):
			var a: Vector2 = pl[i]
			var b: Vector2 = pl[i + 1]
			var ab := b - a
			var t: float = clamp((p - a).dot(ab) / ab.length_squared(), 0.0, 1.0)
			best = min(best, p.distance_to(a + ab * t))
	# ramp path up to the boss plateau
	var a := Vector2(52, -52)
	var b := BOSS_CENTER
	var ab := b - a
	var t: float = clamp((p - a).dot(ab) / ab.length_squared(), 0.0, 1.0)
	best = min(best, p.distance_to(a + ab * t))
	return best

func height(x: float, z: float) -> float:
	var base := 1.2 + noise.get_noise_2d(x, z) * 2.2 + noise3.get_noise_2d(x, z) * 0.25
	var hm := hill_mask(x, z)
	base += hm * (5.0 + noise2.get_noise_2d(x, z) * 5.0 + 1.5)
	# ramp towards the plateau along the boss path
	var pm := plateau_mask(x, z)
	base = lerp(base, 11.0, pm)
	var vm := village_mask(x, z)
	base = lerp(base, 1.0, vm)
	# flatten paths a bit
	var pd := path_dist(x, z)
	var pf := 1.0 - smoothstep(1.5, 4.0, pd)
	if pm < 0.01 and vm < 0.01:
		base = lerp(base, round(base * 2.0) / 2.0, pf * 0.0)  # (kept simple)
	var im := island_mask(x, z)
	base = lerp(-7.0, base, im)
	return base

func zone_at(x: float, z: float) -> String:
	if height(x, z) < WATER_Y + 0.3:
		return "water"
	if Vector2(x, z).distance_to(VILLAGE) < 20.0:
		return "village"
	if plateau_mask(x, z) > 0.5:
		return "boss"
	if hill_mask(x, z) > 0.35:
		return "hills"
	if x < -20.0 and z < -14.0:
		return "forest"
	if x < -40.0 and z < 10.0:
		return "forest"
	return "meadow"

func ground_color(x: float, z: float, y: float, slope: float) -> Color:
	var zone := zone_at(x, z)
	var n := noise3.get_noise_2d(x * 1.7, z * 1.7) * 0.5 + 0.5
	var c: Color
	match zone:
		"forest":
			c = Color(0.18, 0.48, 0.28).lerp(Color(0.26, 0.6, 0.32), n)
		"hills":
			c = Color(0.55, 0.6, 0.3).lerp(Color(0.45, 0.56, 0.26), n)
		"boss":
			c = Color(0.5, 0.42, 0.68).lerp(Color(0.6, 0.52, 0.78), n)
		"village":
			c = Color(0.36, 0.72, 0.32).lerp(Color(0.46, 0.8, 0.36), n)
		_:
			c = Color(0.34, 0.72, 0.3).lerp(Color(0.46, 0.82, 0.36), n)
	# path
	var pd := path_dist(x, z)
	var pf := 1.0 - smoothstep(1.8, 3.0, pd + noise3.get_noise_2d(x * 3.0, z * 3.0) * 0.8)
	c = c.lerp(Color(0.82, 0.68, 0.46), pf)
	# village plaza
	var vd := Vector2(x, z).distance_to(VILLAGE)
	if vd < 9.0:
		c = c.lerp(Color(0.78, 0.64, 0.48), 1.0 - smoothstep(7.5, 9.0, vd))
	# sand near water
	if y < 1.3:
		c = c.lerp(Color(0.92, 0.82, 0.55), 1.0 - smoothstep(0.4, 1.3, y))
	# cliffs
	if slope > 0.55:
		c = c.lerp(Color(0.55, 0.5, 0.6), smoothstep(0.55, 0.8, slope))
	return c

# ---------------- terrain ----------------
func build_terrain() -> void:
	var n := int(SIZE / STEP) + 1
	var half := SIZE * 0.5
	var verts := PackedVector3Array()
	var cols := PackedColorArray()
	var norms := PackedVector3Array()
	var idx := PackedInt32Array()
	verts.resize(n * n)
	cols.resize(n * n)
	norms.resize(n * n)
	for j in range(n):
		for i in range(n):
			var x := -half + i * STEP
			var z := -half + j * STEP
			var y := height(x, z)
			verts[j * n + i] = Vector3(x, y, z)
	for j in range(n):
		for i in range(n):
			var x := -half + i * STEP
			var z := -half + j * STEP
			var hl := height(x - STEP, z)
			var hr := height(x + STEP, z)
			var hd := height(x, z - STEP)
			var hu := height(x, z + STEP)
			var nrm := Vector3(hl - hr, 2.0 * STEP, hd - hu).normalized()
			norms[j * n + i] = nrm
			var slope := 1.0 - nrm.y
			cols[j * n + i] = ground_color(x, z, verts[j * n + i].y, slope * 2.0)
	for j in range(n - 1):
		for i in range(n - 1):
			var a := j * n + i
			var b := a + 1
			var c := a + n
			var d := c + 1
			idx.append_array([a, b, c, b, d, c])
	var arrays := []
	arrays.resize(Mesh.ARRAY_MAX)
	arrays[Mesh.ARRAY_VERTEX] = verts
	arrays[Mesh.ARRAY_NORMAL] = norms
	arrays[Mesh.ARRAY_COLOR] = cols
	arrays[Mesh.ARRAY_INDEX] = idx
	var mesh := ArrayMesh.new()
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)
	terrain = MeshInstance3D.new()
	terrain.mesh = mesh
	terrain.material_override = G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.0, "rim": 0.0, "spec": 0.0, "shade": 0.62, "mid": 0.85, "tint": Color(0.6, 0.6, 0.85)})
	terrain.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	add_child(terrain)
	terrain_body = StaticBody3D.new()
	terrain_body.collision_layer = 1
	terrain_body.collision_mask = 0
	var cs := CollisionShape3D.new()
	var tri := mesh.create_trimesh_shape()
	tri.backface_collision = true
	cs.shape = tri
	terrain_body.add_child(cs)
	add_child(terrain_body)
	props_body = StaticBody3D.new()
	props_body.collision_layer = 1
	props_body.collision_mask = 0
	add_child(props_body)

