# ---------------- grass ----------------
func build_grass() -> void:
	var count := 16000 if G.quality == "HIGH" else 6000
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	# two crossed blades, each a tapered quad
	for k in range(2):
		var a := k * PI * 0.5
		var dir := Vector3(cos(a), 0, sin(a))
		var w := 0.09
		var h := 0.55
		var p0 := -dir * w
		var p1 := dir * w
		var p2 := dir * w * 0.25 + Vector3(0, h, 0)
		var p3 := -dir * w * 0.25 + Vector3(0, h, 0)
		var nrm := Vector3(0, 0.3, 1).normalized()
		for v in [[p0, Vector2(0, 0)], [p2, Vector2(1, 1)], [p1, Vector2(1, 0)], [p0, Vector2(0, 0)], [p3, Vector2(0, 1)], [p2, Vector2(1, 1)]]:
			st.set_normal(nrm)
			st.set_uv(v[1])
			st.add_vertex(v[0])
	var mesh := st.commit()
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_custom_data = true
	mm.mesh = mesh
	mm.instance_count = count
	var rng := RandomNumberGenerator.new()
	rng.seed = 5
	var placed := 0
	var tries := 0
	while placed < count and tries < count * 6:
		tries += 1
		var x := rng.randf_range(-100, 100)
		var z := rng.randf_range(-100, 100)
		var zone := zone_at(x, z)
		if zone == "water" or zone == "boss":
			continue
		if path_dist(x, z) < 2.2:
			continue
		if zone == "village" and Vector2(x, z).distance_to(VILLAGE) < 10.0:
			continue
		var y := height(x, z)
		if y < 1.1:
			continue
		var t := Transform3D(Basis(Vector3.UP, rng.randf() * TAU).scaled(Vector3(1, rng.randf_range(0.7, 1.4), 1) * (1.3 if zone == "forest" else 1.0)), Vector3(x, y - 0.05, z))
		mm.set_instance_transform(placed, t)
		mm.set_instance_custom_data(placed, Color(rng.randf(), 0, 0, 0))
		placed += 1
	mm.instance_count = placed
	grass_mm = MultiMeshInstance3D.new()
	grass_mm.multimesh = mm
	grass_mat = ShaderMaterial.new()
	grass_mat.shader = preload("res://shaders/grass.gdshader")
	grass_mm.material_override = grass_mat
	grass_mm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(grass_mm)

func set_player_pos(p: Vector3) -> void:
	if grass_mat:
		grass_mat.set_shader_parameter("player_pos", p)

# ---------------- flora & rocks ----------------
func multimesh_of(mesh: Mesh, mat: Material, xforms: Array, colors: Array, shadow: bool = true) -> MultiMeshInstance3D:
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	mm.mesh = mesh
	mm.instance_count = xforms.size()
	for i in range(xforms.size()):
		mm.set_instance_transform(i, xforms[i])
		mm.set_instance_color(i, colors[i])
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = mm
	mmi.material_override = mat
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadow else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mmi)
	return mmi

func free_spot(x: float, z: float, r: float) -> bool:
	for t in trees:
		if Vector2(x, z).distance_to(t[0]) < r + t[1]:
			return false
	return true

func build_flora() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 11
	var trunk_mesh := CylinderMesh.new()
	trunk_mesh.top_radius = 0.22
	trunk_mesh.bottom_radius = 0.34
	trunk_mesh.height = 2.6
	trunk_mesh.radial_segments = 8
	var canopy_mesh := SphereMesh.new()
	canopy_mesh.radius = 1.0
	canopy_mesh.height = 2.0
	canopy_mesh.radial_segments = 14
	canopy_mesh.rings = 8
	var cone_mesh := CylinderMesh.new()
	cone_mesh.top_radius = 0.0
	cone_mesh.bottom_radius = 1.0
	cone_mesh.height = 2.0
	cone_mesh.radial_segments = 10
	var trunk_mat := G.toon(Color(0.5, 0.33, 0.2), {"vcol": true, "outline": 0.03, "rim": 0.2})
	var canopy_mat := G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.035, "rim": 0.4, "wind": 1.0, "shade": 0.55})
	var cone_mat := G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.035, "rim": 0.35, "wind": 0.6, "shade": 0.55})
	var rock_mesh := SphereMesh.new()
	rock_mesh.radius = 1.0
	rock_mesh.height = 2.0
	rock_mesh.radial_segments = 7
	rock_mesh.rings = 4
	var rock_mat := G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.035, "rim": 0.25, "spec": 0.15})
	var bush_mat := G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.03, "rim": 0.4, "wind": 0.8, "shade": 0.55})
	var mush_stem := CylinderMesh.new()
	mush_stem.top_radius = 0.12
	mush_stem.bottom_radius = 0.15
	mush_stem.height = 0.5
	mush_stem.radial_segments = 8
	var trunk_x := []; var trunk_c := []
	var can_x := []; var can_c := []
	var cone_x := []; var cone_c := []
	var rock_x := []; var rock_c := []
	var bush_x := []; var bush_c := []
	var mstem_x := []; var mstem_c := []
	var mcap_x := []; var mcap_c := []
	var flower_x := []; var flower_c := []
	var crystal_x := []; var crystal_c := []
	var tries := 0
	while tries < 9000:
		tries += 1
		var x := rng.randf_range(-105, 105)
		var z := rng.randf_range(-105, 105)
		var zone := zone_at(x, z)
		if zone == "water":
			continue
		var y := height(x, z)
		if y < 1.0:
			continue
		var pd := path_dist(x, z)
		var vd := Vector2(x, z).distance_to(VILLAGE)
		var bd := Vector2(x, z).distance_to(BOSS_CENTER)
		var roll := rng.randf()
		match zone:
			"meadow":
				if pd < 3.5 or vd < 22.0:
					continue
				if roll < 0.08 and free_spot(x, z, 4.0):
					# round tree
					var s := rng.randf_range(0.9, 1.5)
					trunk_x.append(Transform3D(Basis().scaled(Vector3(s, s, s)), Vector3(x, y + 1.2 * s, z)))
					trunk_c.append(Color(1, 1, 1).lerp(Color(0.8, 0.7, 0.6), rng.randf() * 0.4))
					var gc := Color(0.35, 0.8, 0.35).lerp(Color(0.55, 0.9, 0.3), rng.randf())
					if rng.randf() < 0.2:
						gc = Color(1.0, 0.6, 0.75)
					for off in [Vector3(0, 3.4, 0), Vector3(0.8, 2.6, 0.3), Vector3(-0.7, 2.7, -0.5), Vector3(0.1, 2.5, 0.9)]:
						var cs := rng.randf_range(1.1, 1.5) * s
						can_x.append(Transform3D(Basis().scaled(Vector3(cs, cs * 0.9, cs)), Vector3(x, y, z) + off * s))
						can_c.append(gc.lerp(Color(1, 1, 1), rng.randf() * 0.12))
					trees.append([Vector2(x, z), 0.6 * s])
					add_collider(make_cyl_shape(0.4 * s, 3.0), Vector3(x, y + 1.5, z))
				elif roll < 0.14:
					bush_x.append(Transform3D(Basis(Vector3.UP, rng.randf() * TAU).scaled(Vector3(rng.randf_range(0.6, 1.1), 0.5, rng.randf_range(0.6, 1.1))), Vector3(x, y + 0.1, z)))
					bush_c.append(Color(0.3, 0.75, 0.3).lerp(Color(0.5, 0.9, 0.35), rng.randf()))
				elif roll < 0.6:
					flower_x.append(Transform3D(Basis().scaled(Vector3.ONE * rng.randf_range(0.6, 1.0)), Vector3(x, y + 0.3, z)))
					flower_c.append([Color(1, 1, 1), Color(1, 0.7, 0.85), Color(0.75, 0.8, 1), Color(1, 0.9, 0.5)][rng.randi() % 4])
				elif roll < 0.63 and free_spot(x, z, 2.0):
					var s := rng.randf_range(0.5, 1.3)
					rock_x.append(Transform3D(Basis(Vector3.UP, rng.randf() * TAU).scaled(Vector3(s * 1.3, s * 0.8, s)), Vector3(x, y + 0.1, z)))
					rock_c.append(Color(0.7, 0.7, 0.8).lerp(Color(0.55, 0.6, 0.7), rng.randf()))
					add_collider(make_sphere_shape(s * 0.9), Vector3(x, y + 0.2, z))
			"forest":
				if pd < 3.0:
					continue
				if roll < 0.22 and free_spot(x, z, 3.2):
					var s := rng.randf_range(0.9, 1.5)
					trunk_x.append(Transform3D(Basis().scaled(Vector3(s * 0.7, s * 1.6, s * 0.7)), Vector3(x, y + 1.9 * s, z)))
					trunk_c.append(Color(0.75, 0.6, 0.55))
					var cc := Color(0.12, 0.5, 0.45).lerp(Color(0.2, 0.65, 0.4), rng.randf())
					for k in range(3):
						var cs := s * (1.7 - k * 0.4)
						cone_x.append(Transform3D(Basis().scaled(Vector3(cs, cs * 1.1, cs)), Vector3(x, y + 2.6 * s + k * 1.3 * s, z)))
						cone_c.append(cc.lerp(Color(1, 1, 1), k * 0.08))
					trees.append([Vector2(x, z), 0.9 * s])
					add_collider(make_cyl_shape(0.4 * s, 6.0), Vector3(x, y + 3.0, z))
				elif roll < 0.4:
					mstem_x.append(Transform3D(Basis().scaled(Vector3.ONE * rng.randf_range(0.6, 1.4)), Vector3(x, y + 0.2, z)))
					mstem_c.append(Color(0.98, 0.92, 0.8))
					var cs := rng.randf_range(0.6, 1.4)
					mcap_x.append(Transform3D(Basis().scaled(Vector3(cs * 0.4, cs * 0.22, cs * 0.4)), Vector3(x, y + 0.2 + 0.45 * cs, z)))
					mcap_c.append([Color(0.95, 0.3, 0.3), Color(0.9, 0.6, 0.2), Color(0.6, 0.4, 0.9), Color(0.3, 0.8, 0.9)][rng.randi() % 4])
				elif roll < 0.55:
					bush_x.append(Transform3D(Basis(Vector3.UP, rng.randf() * TAU).scaled(Vector3(rng.randf_range(0.6, 1.2), 0.6, rng.randf_range(0.6, 1.2))), Vector3(x, y + 0.1, z)))
					bush_c.append(Color(0.2, 0.6, 0.4).lerp(Color(0.3, 0.75, 0.45), rng.randf()))
				elif roll < 0.75:
					flower_x.append(Transform3D(Basis().scaled(Vector3.ONE * rng.randf_range(0.6, 1.0)), Vector3(x, y + 0.3, z)))
					flower_c.append([Color(0.8, 0.7, 1), Color(0.6, 0.9, 1)][rng.randi() % 2])
			"hills":
				if pd < 3.0 or bd < BOSS_R + 12.0:
					continue
				if roll < 0.14 and free_spot(x, z, 2.5):
					var s := rng.randf_range(0.8, 2.6)
					rock_x.append(Transform3D(Basis(Vector3.UP, rng.randf() * TAU).scaled(Vector3(s * 1.2, s * rng.randf_range(0.7, 1.2), s)), Vector3(x, y + 0.2, z)))
					rock_c.append(Color(0.72, 0.68, 0.62).lerp(Color(0.55, 0.55, 0.65), rng.randf()))
					add_collider(make_sphere_shape(s * 0.95), Vector3(x, y + 0.3, z))
					trees.append([Vector2(x, z), s])
				elif roll < 0.2 and free_spot(x, z, 3.0):
					var s := rng.randf_range(0.7, 1.1)
					trunk_x.append(Transform3D(Basis().scaled(Vector3(s, s, s)), Vector3(x, y + 1.2 * s, z)))
					trunk_c.append(Color(0.85, 0.75, 0.7))
					for off in [Vector3(0, 3.2, 0), Vector3(0.7, 2.6, 0.3), Vector3(-0.6, 2.7, -0.4)]:
						var cs := rng.randf_range(1.0, 1.3) * s
						can_x.append(Transform3D(Basis().scaled(Vector3(cs, cs * 0.9, cs)), Vector3(x, y, z) + off * s))
						can_c.append(Color(0.85, 0.65, 0.3).lerp(Color(0.95, 0.5, 0.3), rng.randf()))
					trees.append([Vector2(x, z), 0.6 * s])
					add_collider(make_cyl_shape(0.4 * s, 3.0), Vector3(x, y + 1.5, z))
				elif roll < 0.35:
					bush_x.append(Transform3D(Basis(Vector3.UP, rng.randf() * TAU).scaled(Vector3(rng.randf_range(0.4, 0.8), 0.4, rng.randf_range(0.4, 0.8))), Vector3(x, y + 0.05, z)))
					bush_c.append(Color(0.6, 0.7, 0.3).lerp(Color(0.75, 0.8, 0.35), rng.randf()))
				elif roll < 0.42:
					crystal_x.append(Transform3D(Basis(Vector3(rng.randf_range(-0.3, 0.3), 1, rng.randf_range(-0.3, 0.3)).normalized(), rng.randf() * TAU).scaled(Vector3(0.3, rng.randf_range(0.8, 1.8), 0.3)), Vector3(x, y + 0.3, z)))
					crystal_c.append([Color(0.5, 0.9, 1), Color(1, 0.6, 0.9), Color(0.7, 1, 0.7)][rng.randi() % 3])
			"village":
				if pd < 3.0 or vd < 14.0:
					continue
				if roll < 0.5:
					flower_x.append(Transform3D(Basis().scaled(Vector3.ONE * rng.randf_range(0.6, 1.0)), Vector3(x, y + 0.3, z)))
					flower_c.append([Color(1, 1, 1), Color(1, 0.7, 0.85), Color(1, 0.9, 0.5)][rng.randi() % 3])
				elif roll < 0.56 and free_spot(x, z, 4.0):
					var s := rng.randf_range(0.9, 1.3)
					trunk_x.append(Transform3D(Basis().scaled(Vector3(s, s, s)), Vector3(x, y + 1.2 * s, z)))
					trunk_c.append(Color(0.9, 0.8, 0.75))
					for off in [Vector3(0, 3.4, 0), Vector3(0.8, 2.6, 0.3), Vector3(-0.7, 2.7, -0.5)]:
						var cs := rng.randf_range(1.1, 1.5) * s
						can_x.append(Transform3D(Basis().scaled(Vector3(cs, cs * 0.9, cs)), Vector3(x, y, z) + off * s))
						can_c.append(Color(1.0, 0.65, 0.8).lerp(Color(1, 0.85, 0.9), rng.randf()))
					trees.append([Vector2(x, z), 0.6 * s])
					add_collider(make_cyl_shape(0.4 * s, 3.0), Vector3(x, y + 1.5, z))
	multimesh_of(trunk_mesh, trunk_mat, trunk_x, trunk_c)
	multimesh_of(canopy_mesh, canopy_mat, can_x, can_c)
	multimesh_of(cone_mesh, cone_mat, cone_x, cone_c)
	multimesh_of(rock_mesh, rock_mat, rock_x, rock_c)
	multimesh_of(canopy_mesh, bush_mat, bush_x, bush_c)
	multimesh_of(mush_stem, G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.02}), mstem_x, mstem_c)
	multimesh_of(canopy_mesh, G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.025, "rim": 0.4, "spec": 0.5}), mcap_x, mcap_c)
	var prism := PrismMesh.new()
	prism.size = Vector3(1, 1, 1)
	multimesh_of(prism, G.toon(Color(1, 1, 1), {"vcol": true, "outline": 0.03, "rim": 0.7, "spec": 0.8, "emission": Color(0.5, 0.8, 1.0), "emission_amount": 0.35}), crystal_x, crystal_c)
	# flowers: billboard quads
	var qm := QuadMesh.new()
	qm.size = Vector2(0.7, 0.7)
	var fm := StandardMaterial3D.new()
	fm.albedo_texture = G.tex("flower")
	fm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA_SCISSOR
	fm.alpha_scissor_threshold = 0.5
	fm.billboard_mode = BaseMaterial3D.BILLBOARD_FIXED_Y
	fm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	fm.vertex_color_use_as_albedo = true
	multimesh_of(qm, fm, flower_x, flower_c, false)

func make_cyl_shape(r: float, h: float) -> CylinderShape3D:
	var s := CylinderShape3D.new()
	s.radius = r
	s.height = h
	return s

func make_sphere_shape(r: float) -> SphereShape3D:
	var s := SphereShape3D.new()
	s.radius = r
	return s

func make_box_shape(sz: Vector3) -> BoxShape3D:
	var s := BoxShape3D.new()
	s.size = sz
	return s

# ---------------- village ----------------
func house(pos: Vector3, rot_y: float, wall: Color, roof: Color, w: float = 5.0, d: float = 4.5, h: float = 3.2) -> void:
	var n := Node3D.new()
	n.position = pos
	n.rotation.y = rot_y
	var wm := G.toon(wall, {"outline": 0.035, "rim": 0.15})
	var rm := G.toon(roof, {"outline": 0.035, "rim": 0.3})
	var beam := G.toon(Color(0.45, 0.28, 0.16), {"outline": 0.03})
	var win := G.toon(Color(1.0, 0.95, 0.6), {"outline": 0.02, "emission": Color(1, 0.9, 0.5), "emission_amount": 0.7})
	n.add_child(Chars.box(Vector3(w, h, d), wm, Vector3(0, h * 0.5, 0)))
	# roof prism
	var pm := PrismMesh.new()
	pm.size = Vector3(w + 1.0, 2.2, d + 1.2)
	var roofn := Chars.mi(pm, rm, Vector3(0, h + 1.1, 0))
	n.add_child(roofn)
	# roof trim/beams
	n.add_child(Chars.box(Vector3(w + 1.2, 0.2, d + 1.4), beam, Vector3(0, h + 0.05, 0)))
	# door
	n.add_child(Chars.box(Vector3(1.0, 1.8, 0.15), beam, Vector3(0.8, 0.9, d * 0.5 + 0.05)))
	n.add_child(Chars.sphere(0.07, G.toon(Color(1, 0.85, 0.3)), Vector3(1.15, 0.95, d * 0.5 + 0.14)))
	# windows
	for wx in [-1.4, 1.4]:
		n.add_child(Chars.box(Vector3(0.9, 0.9, 0.12), win, Vector3(wx, 1.9, d * 0.5 + 0.05)))
		n.add_child(Chars.box(Vector3(1.05, 0.12, 0.2), beam, Vector3(wx, 1.4, d * 0.5 + 0.08)))
		n.add_child(Chars.box(Vector3(0.12, 1.0, 0.16), beam, Vector3(wx, 1.9, d * 0.5 + 0.08)))
		n.add_child(Chars.box(Vector3(1.0, 0.12, 0.16), beam, Vector3(wx, 1.9, d * 0.5 + 0.08)))
	n.add_child(Chars.box(Vector3(0.9, 0.9, 0.12), win, Vector3(0, 1.9, -d * 0.5 - 0.05)))
	# chimney
	n.add_child(Chars.box(Vector3(0.7, 1.6, 0.7), G.toon(Color(0.75, 0.45, 0.4), {"outline": 0.03}), Vector3(-w * 0.3, h + 1.6, 0.4)))
	# flower box
	n.add_child(Chars.box(Vector3(1.0, 0.3, 0.35), beam, Vector3(-1.4, 1.3, d * 0.5 + 0.2)))
	n.add_child(Chars.sphere(0.25, G.toon(Color(1, 0.4, 0.5)), Vector3(-1.6, 1.5, d * 0.5 + 0.2)))
