	n.add_child(Chars.box(Vector3(0.5, 0.1, 0.5), post, Vector3(0, 2.9, 0)))
	n.add_child(Chars.cyl(0.0, 0.3, 0.3, post, Vector3(0, 3.1, 0)))
	add_child(n)

func fence(a: Vector3, b: Vector3) -> void:
	var m := G.toon(Color(0.85, 0.7, 0.5), {"outline": 0.025})
	var len := a.distance_to(b)
	var n := int(len / 1.6) + 1
	var dir := (b - a).normalized()
	for i in range(n + 1):
		var p := a + dir * (len * i / n)
		p.y = height(p.x, p.z)
		add_child(Chars.cyl(0.08, 0.08, 1.0, m, p + Vector3(0, 0.5, 0)))
	var mid := (a + b) * 0.5
	mid.y = (height(a.x, a.z) + height(b.x, b.z)) * 0.5
	var rail := Chars.box(Vector3(len, 0.1, 0.1), m, mid + Vector3(0, 0.75, 0))
	rail.rotation.y = atan2(-dir.z, dir.x)
	add_child(rail)
	var rail2 := Chars.box(Vector3(len, 0.1, 0.1), m, mid + Vector3(0, 0.4, 0))
	rail2.rotation.y = rail.rotation.y
	add_child(rail2)

func build_village() -> void:
	var v := Vector3(VILLAGE.x, 1.0, VILLAGE.y)
	house(v + Vector3(-11, 0, -4), deg_to_rad(35), Color(0.98, 0.9, 0.78), Color(0.9, 0.35, 0.35))
