func signpost(pos: Vector3, text: String, rot_y: float) -> void:
	var n := Node3D.new()
	pos.y = height(pos.x, pos.z)
	n.position = pos
	n.rotation.y = rot_y
	var wood := G.toon(Color(0.7, 0.5, 0.3), {"outline": 0.025})
	n.add_child(Chars.cyl(0.07, 0.09, 1.8, wood, Vector3(0, 0.9, 0)))
	n.add_child(Chars.box(Vector3(1.6, 0.5, 0.1), wood, Vector3(0, 1.6, 0)))
	var l := Label3D.new()
	l.text = text
	l.font = load("res://assets/fonts/fredoka700.ttf")
	l.font_size = 48
	l.pixel_size = 0.006
	l.modulate = Color(0.25, 0.12, 0.05)
	l.position = Vector3(0, 1.6, 0.06)
	n.add_child(l)
	add_child(n)

func build_windmill(pos: Vector3) -> void:
	var n := Node3D.new()
	n.position = pos
	var wall := G.toon(Color(0.95, 0.9, 0.8), {"outline": 0.035, "rim": 0.15})
	n.add_child(Chars.cyl(1.6, 2.2, 7.0, wall, Vector3(0, 3.5, 0), Vector3.ZERO, 10))
	n.add_child(Chars.cyl(0.0, 2.0, 2.2, G.toon(Color(0.35, 0.5, 0.9), {"outline": 0.035}), Vector3(0, 8.1, 0), Vector3.ZERO, 10))
	n.add_child(Chars.box(Vector3(0.8, 1.4, 0.15), G.toon(Color(0.45, 0.28, 0.16)), Vector3(0, 0.7, 2.2)))
	windmill_blades = Node3D.new()
	windmill_blades.position = Vector3(0, 6.6, 2.1)
	var bm := G.toon(Color(0.9, 0.5, 0.4), {"outline": 0.03})
	var sail := G.toon(Color(1, 1, 1), {"outline": 0.03})
	windmill_blades.add_child(Chars.cyl(0.3, 0.3, 0.6, bm, Vector3(0, 0, 0), Vector3(deg_to_rad(90), 0, 0)))
	for i in range(4):
		var b := Node3D.new()
		b.rotation.z = i * PI * 0.5
		b.add_child(Chars.box(Vector3(0.2, 5.0, 0.15), bm, Vector3(0, 2.5, 0)))
		b.add_child(Chars.box(Vector3(1.2, 3.6, 0.06), sail, Vector3(0.6, 3.0, 0.1)))
		windmill_blades.add_child(b)
	n.add_child(windmill_blades)
	add_child(n)
	add_collider(make_cyl_shape(2.0, 8.0), pos + Vector3(0, 4, 0))
	trees.append([Vector2(pos.x, pos.z), 3.5])

# ---------------- boss hill ----------------
func build_boss_hill() -> void:
	var c := Vector3(BOSS_CENTER.x, 11.0, BOSS_CENTER.y)
	var pillar := G.toon(Color(0.5, 0.75, 1.0), {"outline": 0.04, "rim": 0.7, "spec": 0.8, "emission": Color(0.3, 0.6, 1.0), "emission_amount": 0.45})
	var stone := G.toon(Color(0.7, 0.68, 0.85), {"outline": 0.035})
	for i in range(10):
		var a := i * TAU / 10.0 + 0.3
		var p := c + Vector3(cos(a) * (BOSS_R - 1.5), 0, sin(a) * (BOSS_R - 1.5))
		var h := 3.0 + (i % 3) * 1.2
		add_child(Chars.cyl(0.0, 0.9, h, pillar, p + Vector3(0, h * 0.5, 0), Vector3.ZERO, 6))
		add_child(Chars.cyl(1.2, 1.3, 0.5, stone, p + Vector3(0, 0.25, 0), Vector3.ZERO, 8))
		add_collider(make_cyl_shape(1.0, h), p + Vector3(0, h * 0.5, 0))
	# gate at the ramp entrance (towards the village side)
	var gdir := (Vector2(52, -52) - BOSS_CENTER).normalized()
	var gpos := c + Vector3(gdir.x, 0, gdir.y) * (BOSS_R - 3.0)
	var ang := atan2(-gdir.y, gdir.x)
	var gate := Node3D.new()
	gate.position = gpos
	gate.rotation.y = ang
	gate.add_child(Chars.box(Vector3(0.8, 5.0, 0.8), stone, Vector3(0, 2.5, -3.0)))
	gate.add_child(Chars.box(Vector3(0.8, 5.0, 0.8), stone, Vector3(0, 2.5, 3.0)))
	gate.add_child(Chars.box(Vector3(1.0, 0.8, 7.5), stone, Vector3(0, 5.3, 0)))
	var l := Label3D.new()
	l.text = "KING'S HILL"
	l.font = load("res://assets/fonts/luckiest.ttf")
	l.font_size = 72
	l.pixel_size = 0.012
	l.modulate = Color(1, 0.9, 0.4)
	l.outline_modulate = Color(0.3, 0.1, 0.4)
	l.outline_size = 16
	l.position = Vector3(0.6, 5.3, 0)
	l.rotation.y = -PI * 0.5
	gate.add_child(l)
	var barm := G.toon(Color(1.0, 0.8, 0.3), {"outline": 0.03, "emission": Color(1, 0.7, 0.2), "emission_amount": 0.4})
	for k in range(5):
		var bar := Chars.cyl(0.12, 0.12, 4.6, barm, Vector3(0, 2.4, -2.0 + k * 1.0))
		gate.add_child(bar)
		gate_bars.append(bar)
	add_child(gate)
	var gb := StaticBody3D.new()
	gb.collision_layer = 1
	gb.name = "GateBody"
	var cs := CollisionShape3D.new()
	cs.shape = make_box_shape(Vector3(0.6, 5.0, 5.0))
	cs.position = gpos + Vector3(0, 2.5, 0)
	cs.rotation.y = ang
	gb.add_child(cs)
	add_child(gb)
	gb.set_meta("gate", true)
	# throne / decorations in the centre
	add_child(Chars.cyl(3.0, 3.4, 0.4, stone, c + Vector3(0, 0.2, 0), Vector3.ZERO, 12))

func open_gate() -> void:
	if boss_gate_open:
		return
	boss_gate_open = true
	for b in gate_bars:
		var tw := create_tween()
		tw.tween_property(b, "position:y", 7.5, 1.2).set_trans(Tween.TRANS_BACK).set_ease(Tween.EASE_IN)
	var gb := get_node_or_null("GateBody")
	if gb:
		gb.queue_free()

# ---------------- sky bits ----------------
func build_clouds() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 21
	var m := G.toon(Color(1, 1, 1), {"outline": 0.06, "rim": 0.0, "shade": 0.8, "mid": 0.92, "tint": Color(0.75, 0.8, 1.0)})
	for i in range(14):
		var c := Node3D.new()
		c.position = Vector3(rng.randf_range(-150, 150), rng.randf_range(34, 55), rng.randf_range(-150, 150))
		var s := rng.randf_range(1.0, 2.2)
		for k in range(rng.randi_range(4, 7)):
			var p := Vector3(rng.randf_range(-4, 4), rng.randf_range(-0.6, 1.2), rng.randf_range(-1.5, 1.5)) * s
			var r := rng.randf_range(1.6, 3.2) * s
			var sp := Chars.sphere(r, m, p, Vector3(1, 0.65, 1), 12)
			sp.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
			c.add_child(sp)
		c.set_meta("speed", rng.randf_range(0.5, 1.3))
		add_child(c)
		clouds.append(c)

func build_islands() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = 33
	var rock := G.toon(Color(0.55, 0.5, 0.65), {"outline": 0.06, "rim": 0.2})
	var grass := G.toon(Color(0.45, 0.85, 0.4), {"outline": 0.06, "rim": 0.3})
	var canopy := G.toon(Color(0.4, 0.85, 0.45), {"outline": 0.05, "rim": 0.4})
	var trunk := G.toon(Color(0.5, 0.33, 0.2), {"outline": 0.04})
	for i in range(4):
		var a := i * TAU / 4.0 + 0.7
		var n := Node3D.new()
		n.position = Vector3(cos(a) * 165, rng.randf_range(22, 40), sin(a) * 165)
		var s := rng.randf_range(0.8, 1.4)
		n.add_child(Chars.cyl(0.0, 7.0 * s, 9.0 * s, rock, Vector3(0, -4.5 * s, 0), Vector3(PI, 0, 0), 9))
		n.add_child(Chars.cyl(7.5 * s, 7.2 * s, 1.6 * s, grass, Vector3(0, 0.8 * s, 0), Vector3.ZERO, 12))
		for k in range(3):
			var p := Vector3(rng.randf_range(-3, 3), 1.6 * s, rng.randf_range(-3, 3)) * s
			n.add_child(Chars.cyl(0.3 * s, 0.4 * s, 3.0 * s, trunk, p + Vector3(0, 1.5 * s, 0)))
			n.add_child(Chars.sphere(2.0 * s, canopy, p + Vector3(0, 3.5 * s, 0), Vector3(1, 0.85, 1), 12))
		n.set_meta("phase", rng.randf() * TAU)
		add_child(n)
		islands.append(n)

func build_chests() -> void:
	var spots := [Vector2(-30, 20), Vector2(-56, -30), Vector2(30, -32), Vector2(66, 6), Vector2(-12, 60), Vector2(48, 38), Vector2(-70, -72), Vector2(62, -62)]
	var i := 0
	for s in spots:
		var ch := Chest.new()
		ch.id = i
		ch.position = Vector3(s.x, height(s.x, s.y), s.y)
		if i == 7:
			ch.position.y = 11.4
		add_child(ch)
		chests.append(ch)
		i += 1

func _process(delta: float) -> void:
	if windmill_blades:
		windmill_blades.rotation.z += delta * 0.8
	var t := Time.get_ticks_msec() * 0.001
	for c in clouds:
		c.position.x += delta * c.get_meta("speed")
		if c.position.x > 170:
			c.position.x = -170
	for n in islands:
		n.position.y += sin(t * 0.4 + n.get_meta("phase")) * delta * 0.4

