	player.dizzy_out.connect(on_dizzy)
	hud = HUD.new()
	hud.main = self
	add_child(hud)
	build_title_scene()
	apply_quality()
	G.music("village")
	if G.selftest:
		call_deferred("run_selftest")
	var args := OS.get_cmdline_user_args()
	for a in args:
		if a.begins_with("--screen="):
			call_deferred("debug_screen", a.substr(9))

func calc_stats() -> Dictionary:
	var st := {"dmg": 0, "hearts": 0, "speed": 0, "crit": 0, "area": 0, "loot": 0, "xp": 0, "energy": 0, "regen": 0, "magnet": 0, "slam": 0, "dash": 0, "whirl": 0}
	for slot in Items.SLOTS:
		var it: Dictionary = G.data["equip"].get(slot, {})
		if it.is_empty():
			continue
		var t := Items.total_stats(it)
		for k in t.keys():
			st[k] = st.get(k, 0) + t[k]
	var nodes := Passives.nodes()
	for id in G.data["passives"]:
		if nodes.has(id):
			for k in nodes[id]["stats"].keys():
				st[k] = st.get(k, 0) + nodes[id]["stats"][k]
	st["hearts"] += G.data["max_hearts"] - 5
	return st

func open_tree() -> void:
	if state != "play":
		return
	state = "tree"
	hud.refresh_tree()
	hud.show_only("tree")

func allocate_passive(id: String) -> bool:
	if G.data["points"] <= 0 or id in G.data["passives"]:
		return false
	var nodes := Passives.nodes()
	if not nodes.has(id):
		return false
	var ok := false
	for l in nodes[id]["links"]:
		if l in G.data["passives"]:
			ok = true
	if not ok:
		return false
	G.data["passives"].append(id)
	G.data["points"] -= 1
	G.save_data()
	G.sfx("levelup", 1.3, -6)
	player.refresh_gear()
	hud.update_stats()
	return true

func apply_quality() -> void:
	var high := G.quality == "HIGH"
	if world.sun:
		world.sun.shadow_enabled = true
		world.sun.directional_shadow_max_distance = 70.0 if high else 40.0
	if world.env:
		world.env.environment.glow_enabled = high and not G.headless
	if world.grass_mm:
		world.grass_mm.visible = true
		world.grass_mm.multimesh.visible_instance_count = -1 if high else int(world.grass_mm.multimesh.instance_count * 0.4)
	get_viewport().scaling_3d_scale = 1.0 if high else 0.75
	get_viewport().msaa_3d = Viewport.MSAA_2X if high else Viewport.MSAA_DISABLED

# ---------------- title ----------------
func build_title_scene() -> void:
	title_cam = Camera3D.new()
	title_cam.fov = 55
	add_child(title_cam)
	title_cam.current = true
	# show the hero posing near the fountain with slimes bouncing around
	player.visible = true
	for i in range(3):
		var m := Monster.new()
		m.kind = ["slime", "pinky", "slime"][i]
		m.main = self
		m.position = world.fountain_pos + Vector3(-3 + i * 3, 1.0, -4 + (i % 2) * 2)
		monsters_root.add_child(m)
		title_slimes.append(m)

func _process(delta: float) -> void:
	if state == "title":
		title_t += delta
		var c := world.fountain_pos + Vector3(4, 1.2, 4)
		var a := title_t * 0.25
		title_cam.position = c + Vector3(cos(a) * 7.0, 2.6 + sin(title_t * 0.5) * 0.4, sin(a) * 7.0)
		title_cam.look_at(c + Vector3(0, 0.9, 0), Vector3.UP)
		return
	if state == "play":
		play_t += delta
		# automatic quality: drop to FAST if the first seconds run slowly on this device
		if not fps_checked and play_t > 4.0 and not G.headless:
			fps_acc += delta
			fps_n += 1
			if fps_acc > 6.0:
				fps_checked = true
				var fps := fps_n / fps_acc
				if fps < 38.0 and G.quality == "HIGH" and not OS.has_feature("web_playwright"):
					G.quality = "FAST"
					G.save_data()
					apply_quality()
					hud.banner("FAST GRAPHICS ON", "so the game stays smooth", HUD.BLUE)
		if bot_fight:
			bot_t += delta
			var best: Monster = null
			var bd := 99.0
			for m in monsters_root.get_children():
				if m is Monster and m.alive:
					var d: float = m.global_position.distance_to(player.global_position)
					if d < bd:
						bd = d
						best = m
			if best:
				var to := best.global_position - player.global_position
				to.y = 0
				player.facing = to.normalized()
				if int(bot_t * 2.5) % 2 == 0:
					player.want_attack = true
		spawn_t -= delta
		if spawn_t <= 0.0:
			spawn_t = 1.5
			maintain_population()
		update_interact()
		if boss and is_instance_valid(boss) and boss.alive:
			hud.set_boss(boss.hp, boss.max_hp, player.global_position.distance_to(boss.global_position) < 45.0)
		else:
			hud.set_boss(0, 1, false)
		world.set_player_pos(player.global_position)
		# music by zone
		var z := world.zone_at(player.global_position.x, player.global_position.z)
		if z == "boss" and boss and is_instance_valid(boss) and boss.alive:
			G.music("boss")
		elif z == "village":
			G.music("village")
		else:
			G.music("meadow")

func start_game() -> void:
	for m in title_slimes:
		if is_instance_valid(m):
			m.queue_free()
	title_slimes.clear()
	title_cam.current = false
	player.cam.current = true
	player.global_position = world.fountain_pos + Vector3(0, 1.5, 5.5)
	player.facing = Vector3(0.6, 0, -0.8).normalized()
	player.refresh_gear()
	player.hearts = player.max_hearts
	player.energy = player.max_energy
	state = "play"
	hud.show_only("game")
	hud.update_stats()
	G.data["played"] += 1
	G.save_data()
	spawn_t = 0.0
	if G.data["quest"] == 0 and G.data["qprog"] == 0 and G.data["played"] <= 1:
		hud.banner("GO TALK TO MAYOR PIP!", "He's by the fountain", HUD.GREEN)
	if G.data["quest"] >= 4:
		world.open_gate()
	spawn_boss_if_needed()

func to_title() -> void:
	G.save_data()
	state = "title"
	player.cam.current = false
	title_cam.current = true
	hud.show_only("title")
	G.music("village")

func pause() -> void:
	if state != "play":
		return
	state = "pause"
	hud.show_only("pause")

func resume() -> void:
	state = "play"
	hud.show_only("game")
	hud.update_stats()

func open_bag() -> void:
	if state != "play":
		return
	state = "bag"
	hud.refresh_bag()
	hud.show_only("bag")

func open_shop() -> void:
	state = "shop"
	restock_shop()
	hud.refresh_shop()
	hud.show_only("shop")

func teleport_home() -> void:
	player.global_position = world.fountain_pos + Vector3(4, 1.5, 4)
	player.velocity = Vector3.ZERO
	resume()

func confirm_reset() -> void:
	hud.show_dialog("Start over?", ["This wipes your hero: coins, swords, hats, quests... everything!", "Tap PLAY afterwards if you really want a fresh start. (Press the title button to cancel.)"], func():
		G.reset_data()
		player.refresh_gear()
		hud.show_only("title")
		state = "title")
	state = "dialog"

func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		if state == "play":
			pause()
		elif state in ["pause", "bag", "shop", "tree"]:
			resume()
	if event.is_action_pressed("tree"):
		if state == "play":
			open_tree()
		elif state == "tree":
			resume()
	if event.is_action_pressed("bag"):
		if state == "play":
			open_bag()
		elif state == "bag":
			resume()

# ---------------- population ----------------
func count_zone(zone: String) -> int:
	var n := 0
	for m in monsters_root.get_children():
		if m is Monster and m.alive and m.spawner_zone == zone:
			n += 1
	return n

func maintain_population() -> void:
	for zone in ZONE_POP.keys():
		var want: int = ZONE_POP[zone] if G.quality == "HIGH" else int(ZONE_POP[zone] * 0.7)
		var have := count_zone(zone)
		var tries := 0
		while have < want and tries < 10:
			tries += 1
			var p := random_spot(zone)
			if p == Vector3.ZERO:
				continue
			if p.distance_to(player.global_position) < 16.0:
				continue
			var kinds: Array = ZONE_KINDS[zone]
			var pack_n := randi_range(2, 5)
			var leader := randf()
			var lv_range: Array = ZONE_LEVEL[zone]
			var lvl := randi_range(lv_range[0], lv_range[1])
			for i in range(pack_n):
				var off := Vector3(randf_range(-3, 3), 0, randf_range(-3, 3))
				var pp := p + off
				pp.y = world.height(pp.x, pp.z) + 0.5
				if world.zone_at(pp.x, pp.z) != zone or not world.free_spot(pp.x, pp.z, 1.0):
					continue
				var rarity := "normal"
				if i == 0 and leader < 0.05:
					rarity = "rare"
				elif randf() < 0.1:
					rarity = "magic"
				spawn_monster(kinds[randi() % kinds.size()], pp, zone, rarity, lvl)
				have += 1

func random_spot(zone: String) -> Vector3:
	var rects := {"meadow": [Vector2(-75, 20), Vector2(75, 85)], "forest": [Vector2(-90, -90), Vector2(-20, 10)], "hills": [Vector2(25, -45), Vector2(90, 30)]}
	var r: Array = rects[zone]
	for i in range(30):
		var x := randf_range(r[0].x, r[1].x)
		var z := randf_range(r[0].y, r[1].y)
		if world.zone_at(x, z) != zone:
			continue
		if not world.free_spot(x, z, 1.5):
			continue
		var y := world.height(x, z)
		if y < 1.0:
			continue
		return Vector3(x, y + 0.5, z)
	return Vector3.ZERO

func spawn_monster(kind: String, pos: Vector3, zone: String, rarity: String = "normal", level: int = 1) -> Monster:
	var m := Monster.new()
	m.kind = kind
	m.main = self
	m.spawner_zone = zone
	m.rarity = rarity
	m.level = level
	m.position = pos
	monsters_root.add_child(m)
	if not G.headless:
		fx.sparkle(pos + Vector3(0, 0.5, 0), Color(1, 1, 1))
	return m

func spawn_boss_if_needed() -> void:
	if G.data["quest"] < 4:
		return
	if boss and is_instance_valid(boss) and boss.alive:
		return
	var c := Vector3(World.BOSS_CENTER.x, 11.6, World.BOSS_CENTER.y)
	boss = spawn_monster("king", c, "boss", "normal", 16)
	boss_active = true

func on_monster_poofed(m: Monster) -> void:
	G.data["bonks"] += 1
	bonks_since_flask += 1
	if bonks_since_flask >= 6 and G.data["flask"] < 3:
		bonks_since_flask = 0
		G.data["flask"] += 1
		fx.text(player.global_position + Vector3(0, 2.2, 0), "+1 FLASK", Color(1, 0.6, 0.8), 0.8, 1.0, false)
		G.sfx("blip", 1.4, -6)
	var xp: int = int(m.data["xp"] * (1.0 + 0.1 * m.level) * (1.0 + float(player.stats.get("xp", 0)) / 100.0))
	match m.rarity:
		"magic": xp *= 2
		"rare": xp *= 4
	add_xp(xp)
	fx.text(m.global_position + Vector3(0, 2.2, 0), "+%d XP" % xp, Color(0.6, 0.95, 1.0), 0.8, 1.0, false)
	var q := current_quest()
	if not q.is_empty() and q["kind"] == "bonk" and m.kind in q["target"]:
		quest_progress(1)
	if m.boss:
		boss_active = false
		G.data["boss_beaten"] += 1
		hud.banner("KING SLIME BOUNCED!", "He poofed all the way home!", HUD.PINK)
		G.sfx("victory")
		if not q.is_empty() and q["kind"] == "boss":
			quest_progress(1)
		if m.spawner_zone == "boss" and G.data["quest"] > 4:
			pass
	hud.update_stats()
	G.save_data()

# ---------------- loot & xp ----------------
func spawn_loot(pos: Vector3, items: Array) -> void:
	for it in items:
		var l := Loot.new()
		l.kind = it[0]
		if it[0] == "item":
			l.item = it[1]
		else:
			l.amount = it[1]
		l.main = self
		l.position = pos + Vector3(0, 0.6, 0)
		loot_root.add_child(l)

func on_loot(kind: String, amount: int, pos: Vector3) -> void:
	match kind:
		"coin":
			G.data["coins"] += amount
			G.sfx("coin", randf_range(0.95, 1.2), -6)
			fx.sparkle(pos, Color(1, 0.9, 0.3))
		"gem":
			G.data["gems"] += amount
			G.sfx("gem")
			fx.text(pos + Vector3(0, 0.6, 0), "+%d GEM%s" % [amount, "S" if amount > 1 else ""], Color(0.6, 0.9, 1.0), 0.9, 0.9, false)
			fx.sparkle(pos, Color(0.5, 0.9, 1.0))
		"heart":
			player.heal(amount)
			G.sfx("heart")
			fx.text(pos + Vector3(0, 0.6, 0), "+HEART", Color(1, 0.5, 0.6), 0.9, 0.9, false)
		_:
			G.data["mats"][kind] += amount
			G.sfx("pickup", randf_range(0.9, 1.1))
			fx.text(pos + Vector3(0, 0.6, 0), "+%d %s" % [amount, Chars.MATS[kind]["name"]], Color(1, 1, 1), 0.8, 0.9, false)
			var q := current_quest()
			if not q.is_empty() and q["kind"] == "mat" and kind in q["target"]:
				quest_progress(amount)
	hud.update_stats()

func on_item_pickup(item: Dictionary, pos: Vector3) -> bool:
	if G.data["inv"].size() >= 24:
		if int(play_t * 2.0) % 6 == 0:
			fx.text(pos + Vector3(0, 1.5, 0), "BAG FULL! Sell stuff at Mimi's", Color(1, 0.6, 0.6), 0.8, 1.0, false)
		return false
	G.data["inv"].append(item)
	var col := Items.color(item)
	G.sfx("gem" if item["rarity"] != "normal" else "pickup", 1.0 if item["rarity"] != "unique" else 0.8)
	fx.text(pos + Vector3(0, 1.2, 0), item["name"], col, 1.0, 1.3, false)
	fx.sparkle(pos, col)
	if item["rarity"] == "unique":
		hud.banner("UNIQUE ITEM!", item["name"], Items.RARITY_COLORS["unique"])
	elif item["rarity"] == "rare":
		fx.burst(pos, col, 14, 5.0, 0.8)
	var eq: Dictionary = G.data["equip"].get(item["slot"], {})
	if eq.is_empty() or Items.score(item) > Items.score(eq):
		fx.text(pos + Vector3(0, 2.0, 0), "BETTER! Equip it in your BAG", Color(0.5, 1.0, 0.6), 0.8, 1.4, false)
		hud.bag_badge = true
	G.save_data()
	hud.update_stats()
	return true

func equip_item(item: Dictionary) -> void:
	var slot: String = item["slot"]
	var old: Dictionary = G.data["equip"].get(slot, {})
	G.data["inv"].erase(item)
	if not old.is_empty() and old.get("id", 0) != 0:
		G.data["inv"].append(old)
	G.data["equip"][slot] = item
	G.save_data()
	G.sfx("buy")
	player.refresh_gear()
	fx.burst(player.global_position + Vector3(0, 1.2, 0), Items.color(item), 16, 6.0, 0.7)
	hud.update_stats()

func sell_item(item: Dictionary) -> void:
	var v := Items.sell_value(item)
	G.data["inv"].erase(item)
	G.data["coins"] += v
	G.save_data()
	G.sfx("coin", 1.1)
	hud.update_stats()

func xp_needed(level: int) -> int:
	return 20 + level * level * 10

func add_xp(n: int) -> void:
	G.data["xp"] += n
	while G.data["xp"] >= xp_needed(G.data["level"]):
		G.data["xp"] -= xp_needed(G.data["level"])
		G.data["level"] += 1
		G.data["points"] += 1
		G.sfx("levelup")
		var sub := "+1 SKILL POINT: open the TREE"
		if G.data["level"] % 3 == 0 and G.data["max_hearts"] < 10:
			G.data["max_hearts"] += 1
			sub = "+1 MAX HEART, +1 SKILL POINT"
		player.refresh_gear()
		player.heal(10)
		player.energy = player.max_energy
		hud.banner("LEVEL %d!" % G.data["level"], sub, HUD.YELLOW)
		fx.burst(player.global_position + Vector3(0, 1, 0), Color(1, 0.9, 0.4), 24, 8.0, 0.9)
		fx.ring(player.global_position + Vector3(0, 0.2, 0), Color(1, 0.9, 0.4))

# ---------------- quests ----------------
func current_quest() -> Dictionary:
	var i: int = G.data["quest"]
	if i < 0 or i >= QUESTS.size():
		return {}
	return QUESTS[i]

func quest_progress(n: int) -> void:
	var q := current_quest()
	if q.is_empty():
		return
	var before: int = G.data["qprog"]
	G.data["qprog"] = min(before + n, q["n"])
	if before < q["n"] and G.data["qprog"] >= q["n"]:
		G.sfx("quest")
		hud.banner("QUEST DONE!", "Go back to Mayor Pip", HUD.GREEN)
	hud.update_stats()

func quest_started(q: Dictionary) -> bool:
	# a quest is "started" once Pip has given the intro (qprog >= 0 and a flag)
	return G.data.get("qstarted", -1) == G.data["quest"]

func talk_pip() -> void:
	var q := current_quest()
	if q.is_empty():
		hud.show_dialog("Mayor Pip", ["You're the Hero of the Meadow! The island is yours to explore.", "Monsters keep coming back, so keep bonking and collecting. Mimi has more gear!", "Total bonks so far: %d. Amazing." % G.data["bonks"]], func(): resume())
		state = "dialog"
		return
	if G.data.get("qstarted", -1) != G.data["quest"]:
		G.data["qstarted"] = G.data["quest"]
		G.save_data()
		hud.show_dialog("Mayor Pip", q["intro"], func():
			resume()
			hud.banner("NEW QUEST!", q["title"], HUD.YELLOW)
			if q["kind"] == "boss":
				world.open_gate()
				spawn_boss_if_needed())
		state = "dialog"
		return
	if G.data["qprog"] >= q["n"]:
		var rw: Dictionary = q["reward"]
		hud.show_dialog("Mayor Pip", q["done"], func():
			G.data["coins"] += rw["coins"]
			G.data["gems"] += rw["gems"]
			fx.text(player.global_position + Vector3(0, 2, 0), "+%d COINS  +%d GEMS" % [rw["coins"], rw["gems"]], HUD.YELLOW, 1.0, 1.2, false)
			G.sfx("buy")
			if q["kind"] == "boss":
				var crown := {"id": randi(), "slot": "helmet", "base": "crown", "base_name": "Crown", "name": "Crown of the Meadow", "rarity": "unique", "level": 16, "stats": {"hearts": 3, "loot": 30, "xp": 20}, "implicit": {"hearts": 2}, "flavor": "For the Hero of the Meadow."}
				if G.data["inv"].size() < 24:
					G.data["inv"].append(crown)
				else:
					G.data["equip"]["helmet"] = crown
				player.refresh_gear()
				hud.banner("HERO OF THE MEADOW!", "You got the Crown of the Meadow!", HUD.PINK)
			G.data["quest"] += 1
			G.data["qprog"] = 0
			G.save_data()
			resume()
			if G.data["quest"] >= 4:
				world.open_gate()
			spawn_boss_if_needed())
		state = "dialog"
		return
	var left: int = q["n"] - G.data["qprog"]
	hud.show_dialog("Mayor Pip", ["%s. You still need %d more. You can do it!" % [q["text"], left]], func(): resume())
	state = "dialog"

func talk_mimi() -> void:
	var lines := ["Hi hero! Welcome to my shop. I sell gear and buy your loot.", "Blue items are Magic, yellow are Rare, orange are Unique. The good stuff!"]
	if G.data["played"] > 1 or G.data["quest"] > 0:
		lines = ["Welcome back! Fresh gear today, and I'll buy anything you don't need."]
	hud.show_dialog("Mimi", lines, func(): open_shop())
	state = "dialog"

func restock_shop(force: bool = false) -> void:
	if force or G.data["shop"].is_empty() or G.data["shop_level"] != G.data["level"]:
		G.data["shop"] = []
		G.data["shop_level"] = G.data["level"]
		var lvl: int = G.data["level"]
		for i in range(5):
			var r := "magic" if i < 3 else "rare"
			var slot: String = Items.SLOTS[i % Items.SLOTS.size()]
			G.data["shop"].append(Items.generate(lvl + 1, 0.0, r, slot))
		G.save_data()

func shop_price(item: Dictionary) -> int:
	return Items.sell_value(item) * 3 + 20

func buy_item(item: Dictionary) -> void:
	var price := shop_price(item)
	if G.data["coins"] < price or G.data["inv"].size() >= 24:
		return
	G.data["coins"] -= price
	G.data["shop"].erase(item)
	G.data["inv"].append(item)
	G.save_data()
	G.sfx("buy")
	hud.refresh_shop()
	hud.update_stats()
	hud.banner("NEW GEAR!", item["name"], Items.color(item))

func buy_heart() -> void:
	var cost: int = 80 * G.data["max_hearts"]
	if G.data["coins"] < cost or G.data["gems"] < 3 or G.data["max_hearts"] >= 10:
		return
	G.data["coins"] -= cost
	G.data["gems"] -= 3
	G.data["max_hearts"] += 1
	player.refresh_gear()
	player.heal(10)
	G.save_data()
	G.sfx("buy")
	hud.update_stats()
	hud.refresh_shop()

func reroll_shop() -> void:
	if G.data["coins"] < 30:
		return
	G.data["coins"] -= 30
	restock_shop(true)
	G.sfx("buy")
	hud.refresh_shop()
	hud.update_stats()

func update_interact() -> void:
	interact_target = null
	interact_kind = ""
	var pp := player.global_position
	var best := 3.2
	for key in world.npcs.keys():
		var n: Dictionary = world.npcs[key]
		var d: float = pp.distance_to(n["pos"])
		if d < best:
			best = d
			interact_target = key
			interact_kind = "npc"
	for ch in world.chests:
		if ch.opened:
			continue
		var d: float = pp.distance_to(ch.position)
		if d < best:
			best = d
			interact_target = ch
			interact_kind = "chest"
	if pp.distance_to(world.fountain_pos) < 4.2 and player.hearts < player.max_hearts:
		if best > 3.0:
			interact_target = "fountain"
			interact_kind = "fountain"
	var txt := ""
	match interact_kind:
		"npc":
			txt = "Talk to %s  (E)" % world.npcs[interact_target]["name"]
		"chest":
			txt = "Open the chest  (E)"
		"fountain":
			txt = "Drink: hearts back!  (E)"
	hud.show_prompt(txt)

func try_interact() -> void:
	if state != "play" or interact_kind == "":
		return
	match interact_kind:
		"npc":
			if interact_target == "pip":
				talk_pip()
			else:
				talk_mimi()
		"chest":
			var ch: Chest = interact_target
			var loot: Array = ch.open()
			G.sfx("chest")
			fx.burst(ch.position + Vector3(0, 1, 0), Color(1, 0.9, 0.4), 20, 7.0, 0.8)
			spawn_loot(ch.position + Vector3(0, 0.8, 0), loot)
			var q := current_quest()
			if not q.is_empty() and q["kind"] == "chest":
				quest_progress(1)
			G.save_data()
		"fountain":
			player.heal(10)
			G.sfx("heart")
			fx.burst(player.global_position + Vector3(0, 1, 0), Color(1, 0.5, 0.6), 14, 5.0, 0.8)
			fx.text(player.global_position + Vector3(0, 2, 0), "HEARTS FULL!", Color(1, 0.5, 0.6))
	update_interact()

func on_dizzy() -> void:
	state = "dizzy"
	hud.show_only("dizzy")
	var t := get_tree().create_timer(2.6)
	t.timeout.connect(func():
		player.revive(world.fountain_pos + Vector3(4, 1.5, 4))
		state = "play"
		hud.show_only("game")
		hud.update_stats()
		fx.burst(player.global_position + Vector3(0, 1, 0), Color(1, 0.6, 0.7), 14, 5.0, 0.8))

