	print("[selftest] " + s)

func run_selftest() -> void:
	await get_tree().process_frame
	G.reset_data()
	G.load_data()
	for ch in world.chests:
		ch.opened = false
	var ok := true
	start_game()
	await wait(0.5)
	log_t("world built: trees=%d chests=%d grass=%d stats=%s" % [world.trees.size(), world.chests.size(), world.grass_mm.multimesh.instance_count, str(player.stats)])
	player.global_position = world.npcs["pip"]["pos"] + Vector3(1.5, 0.5, 0)
	await wait(0.2)
	update_interact()
	try_interact()
	await wait(0.2)
	var guard := 0
	while state == "dialog" and guard < 30:
		hud.advance_dialog()
		await wait(0.05)
		guard += 1
	log_t("quest started: %s state=%s" % [str(current_quest()["title"]), state])
	if not (state == "play"):
		log_t("CHECK FAILED #1: state == 'play'")
		ok = false
	var bonked_before: int = G.data["bonks"]
	var coins_before: int = G.data["coins"]
	for i in range(6):
		var m := spawn_monster("slime", player.global_position + Vector3(2.0, 0.5, 0), "meadow", "magic" if i == 0 else "normal", 2)
		await wait(0.3)
		player.target_monster = m
		var t := 0.0
		while is_instance_valid(m) and m.alive and t < 8.0:
			await wait(0.2)
			t += 0.2
		await wait(0.4)
	await wait(1.5)
	for l in loot_root.get_children():
		if is_instance_valid(l):
			player.global_position = l.global_position
			await wait(0.1)
	log_t("bonks %d -> %d, coins %d -> %d, inv=%d, xp=%d lvl=%d points=%d" % [bonked_before, G.data["bonks"], coins_before, G.data["coins"], G.data["inv"].size(), G.data["xp"], G.data["level"], G.data["points"]])
	if not (G.data["bonks"] - bonked_before >= 5 and G.data["coins"] > coins_before):
		log_t("CHECK FAILED #2: G.data['bonks'] - bonked_before >= 5 and G.data['coins'] > coins_before")
		ok = false
	player.global_position = world.npcs["pip"]["pos"] + Vector3(1.5, 0.5, 0)
	await wait(0.2)
	update_interact()
	try_interact()
	guard = 0
	while state == "dialog" and guard < 30:
		hud.advance_dialog()
		await wait(0.05)
		guard += 1
	log_t("after quest 1: quest=%d coins=%d gems=%d" % [G.data["quest"], G.data["coins"], G.data["gems"]])
	if not (G.data["quest"] == 1):
		log_t("CHECK FAILED #3: G.data['quest'] == 1")
		ok = false
	var ch: Chest = world.chests[0]
	player.global_position = ch.position + Vector3(1.2, 0.5, 0)
	await wait(0.2)
	update_interact()
	if not (interact_kind == "chest"):
		log_t("CHECK FAILED #4: interact_kind == 'chest'")
		ok = false
	try_interact()
	await wait(1.5)
	for l in loot_root.get_children():
		if is_instance_valid(l):
			player.global_position = l.global_position
			await wait(0.05)
	log_t("chest opened: %s coins=%d" % [str(ch.opened), G.data["coins"]])
	if not (ch.opened):
		log_t("CHECK FAILED #5: ch.opened")
		ok = false
	# items
	var it := Items.generate(5, 0.0, "rare", "weapon")
	G.data["inv"].append(it)
	var before_dmg: int = player.dmg_value()
	equip_item(it)
	log_t("equipped %s (%s) stats=%s dmg %d -> %d" % [it["name"], it["rarity"], str(Items.total_stats(it)), before_dmg, player.dmg_value()])
	if not (G.data["equip"]["weapon"]["id"] == it["id"] and player.dmg_value() > before_dmg):
		log_t("CHECK FAILED #6: G.data['equip']['weapon']['id'] == it['id'] and player.dmg_value() > before_dmg")
		ok = false
	var junk := Items.generate(3, 0.0, "magic", "boots")
	G.data["inv"].append(junk)
	var c0: int = G.data["coins"]
	sell_item(junk)
	if not (G.data["coins"] > c0):
		log_t("CHECK FAILED #7: G.data['coins'] > c0")
		ok = false
	var uq := Items.generate(10, 0.0, "unique", "amulet")
	log_t("unique: %s %s" % [uq["name"], str(uq["stats"])])
	if not (uq["rarity"] == "unique"):
		log_t("CHECK FAILED #8: uq['rarity'] == 'unique'")
		ok = false
	# shop
	G.data["coins"] += 2000
	player.global_position = world.npcs["mimi"]["pos"] + Vector3(1.2, 0.5, 1.0)
	player.velocity = Vector3.ZERO
	await wait(0.2)
	update_interact()
	log_t("near mimi: kind=%s d=%.2f state=%s ppos=%s" % [interact_kind, player.global_position.distance_to(world.npcs["mimi"]["pos"]), state, str(player.global_position)])
	try_interact()
	guard = 0
	while state == "dialog" and guard < 30:
		hud.advance_dialog()
		await wait(0.05)
		guard += 1
	log_t("shop state=%s items=%d" % [state, G.data["shop"].size()])
	if not (state == "shop" and G.data["shop"].size() == 5):
		log_t("CHECK FAILED #9: state == 'shop' and G.data['shop'].size() == 5")
		ok = false
	var inv0: int = G.data["inv"].size()
	buy_item(G.data["shop"][0])
	if not (G.data["inv"].size() == inv0 + 1):
		log_t("CHECK FAILED #10: G.data['inv'].size() == inv0 + 1")
		ok = false
	buy_heart()
	resume()
	# passive tree
	G.data["points"] = 3
	if not (allocate_passive("dmg1") and not allocate_passive("dmg2x") and allocate_passive("dmg2")):
		log_t("CHECK FAILED #11: allocate_passive('dmg1') and not allocate_passive('dmg2x') and allocate_passive('dmg2')")
		ok = false
	if not (not allocate_passive("k_iron")):
		log_t("CHECK FAILED #12: not allocate_passive('k_iron')")
		ok = false
	open_tree()
	if not (state == "tree"):
		log_t("CHECK FAILED #13: state == 'tree'")
		ok = false
	resume()
	log_t("passives=%s points=%d stats=%s" % [str(G.data["passives"]), G.data["points"], str(player.stats)])
	# slam + whirl on a pack (in the open meadow)
	player.global_position = world.fountain_pos + Vector3(0, 1.0, 14)
	player.velocity = Vector3.ZERO
	await wait(0.3)
	player.invuln = 12.0
	var pack := []
	for i in range(4):
		pack.append(spawn_monster("shroom", player.global_position + Vector3(1.5 + i * 0.6, 0.5, -1 + i * 0.7), "forest", "normal", 6))
	await wait(0.3)
	player.energy = 100.0
	player.want_slam = true
	await wait(0.8)
	var hurt := 0
	for m in pack:
		if not is_instance_valid(m) or not m.alive or m.hp < m.max_hp:
			hurt += 1
	var ppos := []
	for m in pack:
		if is_instance_valid(m):
			ppos.append(str(m.global_position.round()))
	log_t("slam hurt %d/4 energy=%.0f player=%s pack=%s state=%s atk=%d" % [hurt, player.energy, str(player.global_position.round()), str(ppos), state, player.atk_stage])
	if not (hurt >= 3 and player.slam_cd > 0.0):
		log_t("CHECK FAILED #14: hurt >= 3 and player.slam_cd > 0.0")
		ok = false
	var t := 0.0
	while t < 6.0:
		player.hold_whirl = true
		player.force_whirl = true
		player.energy = max(player.energy, 40.0)
		var near: Monster = player.nearest_monster(60.0)
		if near:
			var tp := near.global_position - player.global_position
			tp.y = 0
			if tp.length() > 1.5:
				player.global_position += tp.normalized() * min(1.0, tp.length() - 1.2)
		await wait(0.2)
		t += 0.2
		var alive_n := 0
		for m in pack:
			if is_instance_valid(m) and m.alive:
				alive_n += 1
		if alive_n == 0:
			break
	player.force_whirl = false
	var alive_n := 0
	for m in pack:
		if is_instance_valid(m) and m.alive:
			alive_n += 1
	log_t("after whirl: alive=%d/4 t=%.1f energy=%.0f" % [alive_n, t, player.energy])
	if not (alive_n <= 1):
		log_t("CHECK FAILED #15: alive_n <= 1")
		ok = false
	# flask
	player.hearts = 1
	G.data["flask"] = 2
	player.want_flask = true
	await wait(0.3)
	log_t("flask: hearts=%d flask=%d" % [player.hearts, G.data["flask"]])
	if not (player.hearts >= 4 and G.data["flask"] == 1):
		log_t("CHECK FAILED #16: player.hearts == 4 and G.data['flask'] == 1")
		ok = false
	for k in ["pinky", "bat", "rock", "bluebat"]:
		var m := spawn_monster(k, player.global_position + Vector3(2.0, 0.5, 0), "meadow", "rare" if k == "rock" else "normal", 8)
		await wait(0.3)
		player.target_monster = m
		t = 0.0
		while is_instance_valid(m) and m.alive and t < 24.0:
			await wait(0.2)
			t += 0.2
		log_t("%s poofed after %.1fs: %s" % [k, t, str(not is_instance_valid(m) or not m.alive)])
		if not ((not is_instance_valid(m) or not m.alive)):
			log_t("CHECK FAILED #17: (not is_instance_valid(m) or not m.alive)")
			ok = false
	var hb := player.hearts
	var sl := spawn_monster("slime", player.global_position + Vector3(1.0, 0.5, 0), "meadow")
	player.invuln = 0.0
	player.bump(sl.global_position, 1)
	if not (player.hearts == hb - 1):
		log_t("CHECK FAILED #18: player.hearts == hb - 1")
		ok = false
	player.hearts = 1
	player.invuln = 0.0
	player.bump(sl.global_position, 1)
	await wait(0.2)
	log_t("dizzy: state=%s" % state)
	if not (state == "dizzy"):
		log_t("CHECK FAILED #19: state == 'dizzy'")
		ok = false
	sl.queue_free()
	await wait(3.0)
	log_t("revived: state=%s hearts=%d" % [state, player.hearts])
	if not (state == "play" and player.hearts == player.max_hearts):
		log_t("CHECK FAILED #20: state == 'play' and player.hearts == player.max_hearts")
		ok = false
	# boss
	G.data["quest"] = 4
	G.data["qstarted"] = 4
	world.open_gate()
	spawn_boss_if_needed()
	player.global_position = boss.global_position + Vector3(3, 0.5, 0)
	G.data["equip"]["weapon"] = Items.generate(22, 0.0, "unique", "weapon")
	player.refresh_gear()
	player.target_monster = boss
	t = 0.0
	while is_instance_valid(boss) and boss.alive and t < 60.0:
		await wait(0.2)
		t += 0.2
		if int(t * 5) % 15 == 0:
			player.want_slam = true
			player.energy = 100.0
	var items_dropped := 0
	for l in loot_root.get_children():
		if is_instance_valid(l) and l.kind == "item":
			items_dropped += 1
	log_t("boss poofed after %.1fs: %s quest_prog=%d items on ground=%d" % [t, str(not is_instance_valid(boss) or not boss.alive), G.data["qprog"], items_dropped])
	if not ((not is_instance_valid(boss) or not boss.alive) and G.data["qprog"] >= 1 and items_dropped >= 3):
		log_t("CHECK FAILED #21: (not is_instance_valid(boss) or not boss.alive) and G.data['qprog'] >= 1 and items_dropped >= 3")
		ok = false
	await wait(2.0)
	log_t("population: meadow=%d forest=%d hills=%d" % [count_zone("meadow"), count_zone("forest"), count_zone("hills")])
	if not (count_zone("meadow") > 8 and count_zone("forest") > 8 and count_zone("hills") > 6):
		log_t("CHECK FAILED #22: count_zone('meadow') > 8 and count_zone('forest') > 8 and count_zone('hills') > 6")
		ok = false
	pause()
	if not (state == "pause"):
		log_t("CHECK FAILED #23: state == 'pause'")
		ok = false
	resume()
	open_bag()
	if not (state == "bag"):
		log_t("CHECK FAILED #24: state == 'bag'")
		ok = false
	resume()
	to_title()
	if not (state == "title"):
		log_t("CHECK FAILED #25: state == 'title'")
		ok = false
	G.save_data()
	log_t("RESULT: " + ("PASS" if ok else "FAIL"))
	get_tree().quit(0 if ok else 1)

func wait(sec: float) -> void:
	await get_tree().create_timer(sec).timeout

