extends Node
# Global helpers: materials, audio, save data. Autoloaded as "G".

const SAVE_PATH := "user://blade_quest.cfg"

var toon_shader: Shader = preload("res://shaders/toon.gdshader")
var outline_shader: Shader = preload("res://shaders/outline.gdshader")
var mat_cache := {}
var tex_cache := {}
var sfx_cache := {}
var sfx_players: Array[AudioStreamPlayer] = []
var sfx_idx := 0
var music_a: AudioStreamPlayer
var music_b: AudioStreamPlayer
var music_cur := ""
var music_fade := 0.0
var sound_on := true
var music_on := true
var headless := false
var selftest := false
var quality := "HIGH"
var is_touch := false

# ---------------- save data ----------------
var data := {}

func default_data() -> Dictionary:
	return {
		"level": 1, "xp": 0, "coins": 0, "gems": 0,
		"mats": {"jelly": 0, "cap": 0, "feather": 0, "pebble": 0},
		"inv": [], "equip": {}, "passives": ["start"], "points": 0, "flask": 3, "flask_fill": 0,
		"shop": [], "shop_level": 0, "version": 2,
		"quest": 0, "qprog": 0, "qstarted": -1,
		"chests": [], "bonks": 0, "boss_beaten": 0,
		"max_hearts": 5, "played": 0,
	}

func _ready() -> void:
	headless = DisplayServer.get_name() == "headless"
	var args := OS.get_cmdline_user_args()
	selftest = "--selftest" in args
	is_touch = DisplayServer.is_touchscreen_available()
	load_data()
	for i in range(12):
		var p := AudioStreamPlayer.new()
		p.bus = "Master"
		add_child(p)
		sfx_players.append(p)
	music_a = AudioStreamPlayer.new()
	music_b = AudioStreamPlayer.new()
	music_a.volume_db = -80
	music_b.volume_db = -80
	add_child(music_a)
	add_child(music_b)

func load_data() -> void:
	data = default_data()
	var cf := ConfigFile.new()
	if cf.load(SAVE_PATH) == OK:
		for k in data.keys():
			if cf.has_section_key("game", k):
				data[k] = cf.get_value("game", k)
		sound_on = cf.get_value("settings", "sound", true)
		music_on = cf.get_value("settings", "music", true)
		quality = cf.get_value("settings", "quality", "HIGH")
	# make sure dict keys exist after updates
	for k in ["jelly", "cap", "feather", "pebble"]:
		if not data["mats"].has(k):
			data["mats"][k] = 0
	if not data.has("equip") or not (data["equip"] is Dictionary):
		data["equip"] = {}
	for slot in Items.SLOTS:
		if not data["equip"].has(slot):
			data["equip"][slot] = Items.starter(slot)
	if not data.has("inv") or not (data["inv"] is Array):
		data["inv"] = []
	if not data.has("passives") or not (data["passives"] is Array) or data["passives"].is_empty():
		data["passives"] = ["start"]
	# points = level - 1 - allocated
	data["points"] = max(0, data["level"] - 1 - (data["passives"].size() - 1))

func save_data() -> void:
	var cf := ConfigFile.new()
	for k in data.keys():
		cf.set_value("game", k, data[k])
	cf.set_value("settings", "sound", sound_on)
	cf.set_value("settings", "music", music_on)
	cf.set_value("settings", "quality", quality)
	cf.save(SAVE_PATH)

func reset_data() -> void:
	data = default_data()
	save_data()

# ---------------- materials ----------------
func toon(color: Color, opts: Dictionary = {}) -> ShaderMaterial:
	var key := str(color) + str(opts)
	if mat_cache.has(key):
		return mat_cache[key]
	var m := ShaderMaterial.new()
	m.shader = toon_shader
	m.set_shader_parameter("albedo", color)
	m.set_shader_parameter("rim_amount", opts.get("rim", 0.35))
	m.set_shader_parameter("spec_amount", opts.get("spec", 0.25))
	m.set_shader_parameter("spec_size", opts.get("spec_size", 0.95))
	m.set_shader_parameter("shade_level", opts.get("shade", 0.5))
	m.set_shader_parameter("mid_level", opts.get("mid", 0.78))
	m.set_shader_parameter("wind", opts.get("wind", 0.0))
	m.set_shader_parameter("alpha", opts.get("alpha", 1.0))
	if opts.has("tint"):
		m.set_shader_parameter("shade_tint", opts["tint"])
	if opts.has("emission"):
		m.set_shader_parameter("emission_color", opts["emission"])
		m.set_shader_parameter("emission_amount", opts.get("emission_amount", 1.0))
	if opts.has("tex"):
		m.set_shader_parameter("tex", tex(opts["tex"]))
		m.set_shader_parameter("use_tex", true)
		m.set_shader_parameter("uv_scale", opts.get("uv_scale", 1.0))
	if opts.get("vcol", false):
		m.set_shader_parameter("use_vcol", true)
	if opts.get("alpha", 1.0) < 1.0:
		m.render_priority = 1
	var ow: float = opts.get("outline", 0.02)
	if ow > 0.0:
		var o := ShaderMaterial.new()
		o.shader = outline_shader
		o.set_shader_parameter("width", ow)
		o.set_shader_parameter("color", opts.get("outline_color", Color(0.16, 0.08, 0.22)))
		o.set_shader_parameter("wind", opts.get("wind", 0.0))
		m.next_pass = o
	mat_cache[key] = m
	return m

func unique_toon(color: Color, opts: Dictionary = {}) -> ShaderMaterial:
	# a copy that can be animated (flash) without touching the cached one
	var base := toon(color, opts)
	var m: ShaderMaterial = base.duplicate()
	if base.next_pass:
		m.next_pass = base.next_pass
	return m

func tex(name: String) -> Texture2D:
	if tex_cache.has(name):
		return tex_cache[name]
	var t: Texture2D = load("res://assets/tex/%s.png" % name)
	tex_cache[name] = t
	return t

# ---------------- audio ----------------
func sfx(name: String, pitch: float = 1.0, vol_db: float = 0.0) -> void:
	if not sound_on or headless:
		return
	var s: AudioStream
	if sfx_cache.has(name):
		s = sfx_cache[name]
	else:
		var path := "res://assets/sfx/%s.wav" % name
		if not ResourceLoader.exists(path):
			return
		s = load(path)
		sfx_cache[name] = s
	var p := sfx_players[sfx_idx]
	sfx_idx = (sfx_idx + 1) % sfx_players.size()
	p.stream = s
	p.pitch_scale = pitch
	p.volume_db = vol_db
	p.play()

func music(name: String) -> void:
	if name == music_cur:
		return
	music_cur = name
	if headless:
		return
	var path := "res://assets/sfx/music_%s.ogg" % name
	if name == "" or not ResourceLoader.exists(path):
		music_fade = 0.0
		return
	var s: AudioStreamOggVorbis = load(path)
	s.loop = true
	# swap: b becomes the new one
	var tmp := music_a
	music_a = music_b
	music_b = tmp
	music_a.stream = s
	music_a.volume_db = -30
	music_a.play()
	music_fade = 1.0

func _process(delta: float) -> void:
	if headless:
		return
	var target := -9.0 if (music_on and music_cur != "") else -80.0
	if music_a.playing:
		music_a.volume_db = move_toward(music_a.volume_db, target, delta * 40.0)
	if music_b.playing:
		music_b.volume_db = move_toward(music_b.volume_db, -80.0, delta * 40.0)
		if music_b.volume_db <= -79.0:
			music_b.stop()

# ---------------- misc ----------------
func rnd(a: float, b: float) -> float:
	return randf_range(a, b)

func fmt(n: int) -> String:
	var s := str(n)
	var out := ""
	var c := 0
	for i in range(s.length() - 1, -1, -1):
		out = s[i] + out
		c += 1
		if c % 3 == 0 and i > 0:
			out = "," + out
	return out

