class_name Items
# ARPG item system: base types per slot, rarities (normal/magic/rare/unique), random affixes, names, stats.

const SLOTS := ["weapon", "helmet", "armor", "boots", "amulet"]
const SLOT_NAMES := {"weapon": "Sword", "helmet": "Hat", "armor": "Tunic", "boots": "Boots", "amulet": "Charm"}
const RARITY_COLORS := {"normal": Color(0.95, 0.95, 0.95), "magic": Color(0.45, 0.65, 1.0), "rare": Color(1.0, 0.9, 0.25), "unique": Color(1.0, 0.55, 0.2)}
const RARITY_NAMES := {"normal": "Normal", "magic": "Magic", "rare": "Rare", "unique": "Unique"}

# base types: [id, name, level, implicit stats]
const BASES := {
	"weapon": [
		["wood", "Wooden Sword", 1, {"dmg": 1}],
		["iron", "Iron Sword", 3, {"dmg": 2}],
		["jelly", "Jelly Blade", 6, {"dmg": 3}],
		["crystal", "Crystal Sword", 10, {"dmg": 4}],
		["flame", "Flame Sword", 15, {"dmg": 6}],
		["rainbow", "Rainbow Blade", 22, {"dmg": 8}],
	],
	"helmet": [
		["cap", "Hero Cap", 1, {"hearts": 1}],
		["catears", "Cat Ears", 5, {"speed": 5}],
		["wizard", "Wizard Hat", 10, {"energy": 20}],
		["crown", "Crown", 18, {"hearts": 2}],
	],
	"armor": [
		["cloth", "Cloth Tunic", 1, {"hearts": 1}],
		["leather", "Leather Vest", 5, {"hearts": 2}],
		["scale", "Scale Coat", 11, {"hearts": 3}],
		["plate", "Hero Plate", 18, {"hearts": 4}],
	],
	"boots": [
		["sandals", "Sandals", 1, {"speed": 4}],
		["boots", "Travel Boots", 5, {"speed": 8}],
		["sprint", "Sprint Boots", 11, {"speed": 12}],
		["rocket", "Rocket Boots", 18, {"speed": 16}],
	],
	"amulet": [
		["string", "String Charm", 1, {"loot": 5}],
		["shell", "Shell Charm", 5, {"loot": 10}],
		["gem", "Gem Charm", 11, {"crit": 5}],
		["star", "Star Charm", 18, {"xp": 15}],
	],
}

# affixes: id -> [display, stat, min, max per tier (3 tiers), prefix name, suffix name]
const AFFIXES := {
	"dmg":     {"text": "+%d bonk power",          "stat": "dmg",    "tiers": [[1, 1], [2, 3], [4, 6]],    "prefix": ["Bonky", "Smashy", "Mighty"],  "suffix": "of Bonking"},
	"hearts":  {"text": "+%d max hearts",          "stat": "hearts", "tiers": [[1, 1], [2, 2], [3, 4]],    "prefix": ["Tough", "Sturdy", "Titanic"], "suffix": "of Hearts"},
	"speed":   {"text": "+%d%% move speed",        "stat": "speed",  "tiers": [[4, 8], [9, 14], [15, 22]], "prefix": ["Quick", "Swift", "Zooming"],  "suffix": "of Zoom"},
	"crit":    {"text": "+%d%% mega bonk chance",  "stat": "crit",   "tiers": [[3, 6], [7, 12], [13, 20]], "prefix": ["Lucky", "Fierce", "Savage"],  "suffix": "of Luck"},
	"area":    {"text": "+%d%% bonk area",         "stat": "area",   "tiers": [[5, 10], [11, 18], [19, 30]], "prefix": ["Wide", "Huge", "Giant"],    "suffix": "of Reach"},
	"loot":    {"text": "+%d%% loot find",         "stat": "loot",   "tiers": [[5, 10], [11, 20], [21, 35]], "prefix": ["Shiny", "Greedy", "Golden"], "suffix": "of Treasure"},
	"xp":      {"text": "+%d%% experience",        "stat": "xp",     "tiers": [[5, 10], [11, 18], [19, 30]], "prefix": ["Clever", "Wise", "Brilliant"], "suffix": "of Learning"},
	"energy":  {"text": "+%d max energy",          "stat": "energy", "tiers": [[10, 20], [21, 35], [36, 60]], "prefix": ["Sparky", "Charged", "Electric"], "suffix": "of Energy"},
	"regen":   {"text": "+%d energy per bonk",     "stat": "regen",  "tiers": [[2, 3], [4, 6], [7, 10]],   "prefix": ["Buzzing", "Humming", "Thundering"], "suffix": "of Buzz"},
	"magnet":  {"text": "+%d%% loot magnet range", "stat": "magnet", "tiers": [[10, 20], [21, 40], [41, 70]], "prefix": ["Magnetic", "Pulling", "Grabby"], "suffix": "of Grabbing"},
}
const AFFIX_ORDER := ["dmg", "hearts", "speed", "crit", "area", "loot", "xp", "energy", "regen", "magnet"]

const UNIQUES := [
	{"slot": "weapon", "base": "jelly",   "name": "Wobbler, the Giggle Blade",  "stats": {"dmg": 5, "area": 40, "crit": 10},           "flavor": "Every bonk makes them laugh."},
	{"slot": "weapon", "base": "flame",   "name": "Toasty",                     "stats": {"dmg": 9, "energy": 30, "regen": 6},         "flavor": "Perfectly warm. Never burns."},
	{"slot": "weapon", "base": "rainbow", "name": "Prismatic Pal",              "stats": {"dmg": 12, "loot": 40, "speed": 10},         "flavor": "The legendary blade of heroes."},
	{"slot": "helmet", "base": "catears", "name": "Nine Lives",                 "stats": {"hearts": 4, "speed": 15},                    "flavor": "Nyaa."},
	{"slot": "helmet", "base": "wizard",  "name": "Thinking Cap",               "stats": {"xp": 40, "energy": 50},                      "flavor": "+100% wizardness."},
	{"slot": "armor",  "base": "plate",   "name": "Marshmallow Armor",          "stats": {"hearts": 6, "regen": 4},                     "flavor": "Soft, squishy, unbreakable."},
	{"slot": "boots",  "base": "rocket",  "name": "Zoomies",                    "stats": {"speed": 35, "crit": 8},                      "flavor": "Zoom zoom zoom."},
	{"slot": "amulet", "base": "star",    "name": "The Lucky Star",             "stats": {"loot": 60, "crit": 12, "magnet": 50},        "flavor": "Wish upon it."},
]

static func base_for(slot: String, level: int, rng: RandomNumberGenerator) -> Array:
	var cands := []
	for b in BASES[slot]:
		if b[2] <= level + 1:
			cands.append(b)
	if cands.is_empty():
		cands.append(BASES[slot][0])
	# prefer higher bases
	var w := []
	var total := 0.0
	for i in range(cands.size()):
		var wt := 1.0 + i * 1.5
		w.append(wt)
		total += wt
	var r := rng.randf() * total
	for i in range(cands.size()):
		r -= w[i]
		if r <= 0.0:
			return cands[i]
	return cands[-1]

static func roll_rarity(level: int, loot_bonus: float, rng: RandomNumberGenerator, force: String = "") -> String:
	if force != "":
		return force
	var r: float = rng.randf() / maxf(1.0, 1.0 + loot_bonus / 100.0)
	if r < 0.02 and level >= 4:
		return "unique"
	if r < 0.14:
		return "rare"
	if r < 0.45:
		return "magic"
	return "normal"

static func generate(level: int, loot_bonus: float = 0.0, force_rarity: String = "", force_slot: String = "") -> Dictionary:
	var rng := RandomNumberGenerator.new()
	rng.randomize()
	var slot: String = force_slot if force_slot != "" else SLOTS[rng.randi() % SLOTS.size()]
	var rarity := roll_rarity(level, loot_bonus, rng, force_rarity)
	if rarity == "unique":
		var pool := []
		for u in UNIQUES:
			if u["slot"] == slot:
				pool.append(u)
		if pool.is_empty():
			rarity = "rare"
		else:
			var u: Dictionary = pool[rng.randi() % pool.size()]
			var base := find_base(slot, u["base"])
			return {"id": rng.randi(), "slot": slot, "base": u["base"], "base_name": base[1], "name": u["name"], "rarity": "unique",
				"level": max(level, base[2]), "stats": u["stats"].duplicate(), "implicit": base[3].duplicate(), "flavor": u["flavor"]}
	var base := base_for(slot, level, rng)
	var n_aff := 0
	match rarity:
		"magic": n_aff = 1 + (1 if rng.randf() < 0.5 else 0)
		"rare": n_aff = 3 + (1 if rng.randf() < 0.5 else 0)
	var stats := {}
	var pool := AFFIX_ORDER.duplicate()
	if slot != "weapon" and rng.randf() < 0.6:
		pool.erase("dmg")
	var prefix := ""
	var suffix := ""
	for i in range(n_aff):
		if pool.is_empty():
			break
		var aid: String = pool[rng.randi() % pool.size()]
		if i == 0 and slot == "weapon":
			aid = "dmg"  # swords always bonk harder
		pool.erase(aid)
		var a: Dictionary = AFFIXES[aid]
		var tier := 0
		if level >= 8:
			tier = 1 if rng.randf() < 0.6 else 0
		if level >= 16:
			tier = 2 if rng.randf() < 0.5 else 1
		var rng_t: Array = a["tiers"][tier]
		stats[aid] = rng.randi_range(rng_t[0], rng_t[1])
		if prefix == "":
			prefix = a["prefix"][tier]
		elif suffix == "":
			suffix = a["suffix"]
	var name: String = base[1]
	if rarity == "magic":
		name = (prefix + " " if prefix != "" else "") + base[1] + (" " + suffix if suffix != "" else "")
	elif rarity == "rare":
		var first := ["Bouncy", "Giggle", "Thunder", "Sparkle", "Rumble", "Jelly", "Comet", "Pancake", "Noodle", "Wobble", "Rainbow", "Pebble"]
		var second := ["Bonker", "Buddy", "Breaker", "Whisper", "Dancer", "Hugger", "Zoomer", "Smasher", "Tickler", "Giant"]
		name = first[rng.randi() % first.size()] + " " + second[rng.randi() % second.size()]
	return {"id": rng.randi(), "slot": slot, "base": base[0], "base_name": base[1], "name": name, "rarity": rarity,
		"level": max(1, base[2]), "stats": stats, "implicit": base[3].duplicate(), "flavor": ""}

static func find_base(slot: String, id: String) -> Array:
	for b in BASES[slot]:
		if b[0] == id:
			return b
	return BASES[slot][0]

static func starter(slot: String) -> Dictionary:
	var b: Array = BASES[slot][0]
	return {"id": 0, "slot": slot, "base": b[0], "base_name": b[1], "name": b[1], "rarity": "normal", "level": 1, "stats": {}, "implicit": b[3].duplicate(), "flavor": ""}

static func total_stats(item: Dictionary) -> Dictionary:
	var out := {}
	for k in item["implicit"].keys():
		out[k] = out.get(k, 0) + item["implicit"][k]
	for k in item["stats"].keys():
		out[k] = out.get(k, 0) + item["stats"][k]
	return out

static func stat_line(stat: String, v: int) -> String:
	if AFFIXES.has(stat):
		return AFFIXES[stat]["text"] % v
	return "+%d %s" % [v, stat]

static func color(item: Dictionary) -> Color:
	return RARITY_COLORS[item["rarity"]]

static func sell_value(item: Dictionary) -> int:
	var v: int = 3 + item["level"] * 2
	match item["rarity"]:
		"magic": v *= 3
		"rare": v *= 8
		"unique": v *= 20
	return v

static func score(item: Dictionary) -> int:
	# rough power score for "better than equipped" arrows
	var s := 0
	var t := total_stats(item)
	for k in t.keys():
		match k:
			"dmg": s += t[k] * 10
			"hearts": s += t[k] * 6
			_: s += t[k]
	return s

