class_name Chars
# Procedural anime-style character builders. All parts are primitive meshes with toon materials.

const SKIN := Color(1.0, 0.86, 0.74)
const ARMOR_COLORS := {"cloth": Color(0.25, 0.55, 1.0), "leather": Color(0.6, 0.38, 0.2), "scale": Color(0.3, 0.7, 0.55), "plate": Color(0.75, 0.8, 0.95)}
const BOOTS_COLORS := {"sandals": Color(0.8, 0.6, 0.35), "boots": Color(0.45, 0.28, 0.18), "sprint": Color(0.2, 0.5, 1.0), "rocket": Color(1.0, 0.4, 0.3)}
const DARK := Color(0.16, 0.08, 0.22)

const SWORDS := {
	"wood":    {"name": "Wooden Sword",  "dmg": 1, "price": 0,    "mats": {},                              "blade": Color(0.76, 0.52, 0.3),  "glow": Color(0, 0, 0),           "glow_amt": 0.0, "desc": "A trusty starter sword."},
	"iron":    {"name": "Iron Sword",    "dmg": 2, "price": 60,   "mats": {"pebble": 3},                   "blade": Color(0.85, 0.88, 0.95), "glow": Color(0, 0, 0),           "glow_amt": 0.0, "desc": "Shiny and strong."},
	"jelly":   {"name": "Jelly Blade",   "dmg": 3, "price": 150,  "mats": {"jelly": 8},                    "blade": Color(0.45, 0.95, 0.55), "glow": Color(0.3, 1.0, 0.4),     "glow_amt": 0.6, "desc": "Wobbly. Bonks extra hard."},
	"crystal": {"name": "Crystal Sword", "dmg": 4, "price": 350,  "mats": {"pebble": 10, "feather": 5},    "blade": Color(0.6, 0.9, 1.0),    "glow": Color(0.4, 0.8, 1.0),     "glow_amt": 1.0, "desc": "Sparkles like the sky."},
	"flame":   {"name": "Flame Sword",   "dmg": 6, "price": 700,  "mats": {"cap": 12, "jelly": 10},        "blade": Color(1.0, 0.55, 0.2),   "glow": Color(1.0, 0.35, 0.1),    "glow_amt": 1.6, "desc": "Hot! (but totally safe)"},
	"rainbow": {"name": "Rainbow Legend","dmg": 9, "price": 1500, "mats": {"jelly": 15, "cap": 15, "feather": 15, "pebble": 15}, "blade": Color(1, 1, 1), "glow": Color(1, 1, 1), "glow_amt": 1.2, "desc": "The legendary blade of heroes."},
}
const SWORD_ORDER := ["wood", "iron", "jelly", "crystal", "flame", "rainbow"]

const HATS := {
	"none":   {"name": "No Hat",       "price": 0,   "mats": {},               "desc": "Just hair."},
	"cap":    {"name": "Hero Cap",     "price": 40,  "mats": {},               "desc": "A cool blue cap."},
	"catears":{"name": "Cat Ears",     "price": 120, "mats": {"feather": 4},   "desc": "Nyaa!"},
	"wizard": {"name": "Wizard Hat",   "price": 250, "mats": {"cap": 6},       "desc": "+100% wizardness."},
	"crown":  {"name": "Hero Crown",   "price": 0,   "mats": {},               "desc": "For beating the King Slime!", "quest": true},
}
const HAT_ORDER := ["none", "cap", "catears", "wizard", "crown"]

const MATS := {
	"jelly":   {"name": "Slime Jelly",   "icon": "icon_jelly"},
	"cap":     {"name": "Mushroom Cap",  "icon": "icon_cap"},
	"feather": {"name": "Fluff Feather", "icon": "icon_feather"},
	"pebble":  {"name": "Shiny Pebble",  "icon": "icon_pebble"},
}

# ---------------- primitives ----------------
static func mi(mesh: Mesh, mat: Material, pos: Vector3 = Vector3.ZERO, scl: Vector3 = Vector3.ONE, rot: Vector3 = Vector3.ZERO) -> MeshInstance3D:
	var n := MeshInstance3D.new()
	n.mesh = mesh
	n.material_override = mat
	n.position = pos
	n.scale = scl
	n.rotation = rot
	n.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	return n

static func sphere(r: float, mat: Material, pos: Vector3 = Vector3.ZERO, scl: Vector3 = Vector3.ONE, seg: int = 20) -> MeshInstance3D:
	var m := SphereMesh.new()
	m.radius = r
	m.height = r * 2.0
	m.radial_segments = seg
	m.rings = int(seg / 2)
	return mi(m, mat, pos, scl)

static func capsule(r: float, h: float, mat: Material, pos: Vector3 = Vector3.ZERO, rot: Vector3 = Vector3.ZERO) -> MeshInstance3D:
	var m := CapsuleMesh.new()
	m.radius = r
	m.height = h
	m.radial_segments = 16
	m.rings = 6
	return mi(m, mat, pos, Vector3.ONE, rot)

static func box(size: Vector3, mat: Material, pos: Vector3 = Vector3.ZERO, rot: Vector3 = Vector3.ZERO) -> MeshInstance3D:
	var m := BoxMesh.new()
	m.size = size
	return mi(m, mat, pos, Vector3.ONE, rot)

static func cyl(rt: float, rb: float, h: float, mat: Material, pos: Vector3 = Vector3.ZERO, rot: Vector3 = Vector3.ZERO, seg: int = 16) -> MeshInstance3D:
	var m := CylinderMesh.new()
	m.top_radius = rt
	m.bottom_radius = rb
	m.height = h
	m.radial_segments = seg
	return mi(m, mat, pos, Vector3.ONE, rot)

static func face(tex_name: String, pos: Vector3, w: float = 0.6) -> Sprite3D:
	var s := Sprite3D.new()
	s.texture = G.tex(tex_name)
	s.pixel_size = w / 256.0
	s.position = pos
	s.shaded = false
	s.double_sided = false
	s.no_depth_test = false
	s.alpha_cut = SpriteBase3D.ALPHA_CUT_DISCARD
	s.render_priority = 2
	return s

# ---------------- hero ----------------
# Returns the visual root and a dictionary of animatable parts.
static func build_hero(equip: Dictionary = {}) -> Dictionary:
	var sword_id: String = equip.get("weapon", {}).get("base", "wood")
	var hat_id: String = equip.get("helmet", {}).get("base", "none")
	var armor_id: String = equip.get("armor", {}).get("base", "cloth")
	var boots_id: String = equip.get("boots", {}).get("base", "sandals")
	var armor_col: Color = ARMOR_COLORS.get(armor_id, Color(0.25, 0.55, 1.0))
	var boots_col: Color = BOOTS_COLORS.get(boots_id, Color(0.45, 0.28, 0.18))
	var root := Node3D.new()
	root.name = "HeroVis"
	root.rotation.y = PI  # modelled with +Z as the front; Godot forward is -Z
	var p := {}
	var skin := G.toon(SKIN, {"rim": 0.25, "outline": 0.03})
	var tunic := G.toon(armor_col, {"rim": 0.4, "outline": 0.03})
	var tunic2 := G.toon(Color(0.95, 0.95, 1.0), {"rim": 0.3})
	var pants := G.toon(Color(0.2, 0.22, 0.45))
	var boots := G.toon(boots_col, {"outline": 0.03})
	var hair := G.toon(Color(0.45, 0.25, 0.12), {"rim": 0.4, "spec": 0.5, "spec_size": 0.92, "outline": 0.03})
	var scarf := G.toon(Color(1.0, 0.3, 0.35), {"rim": 0.4})
	var belt := G.toon(Color(0.5, 0.3, 0.15))
	var gold := G.toon(Color(1.0, 0.8, 0.25), {"spec": 0.8})

	# legs
	for side in [-1, 1]:
		var piv := Node3D.new()
		piv.position = Vector3(0.14 * side, 0.62, 0)
		var leg := capsule(0.11, 0.42, pants, Vector3(0, -0.22, 0))
		piv.add_child(leg)
		var boot := box(Vector3(0.22, 0.14, 0.3), boots, Vector3(0, -0.5, 0.03))
		piv.add_child(boot)
		root.add_child(piv)
		p["leg%s" % ("L" if side < 0 else "R")] = piv
	# body (bobs)
	var body := Node3D.new()
	body.position = Vector3(0, 0.62, 0)
	root.add_child(body)
	p["body"] = body
	body.add_child(capsule(0.3, 0.72, tunic, Vector3(0, 0.36, 0)))
	body.add_child(box(Vector3(0.62, 0.08, 0.62), belt, Vector3(0, 0.3, 0)))
	body.add_child(box(Vector3(0.12, 0.12, 0.05), gold, Vector3(0, 0.3, 0.31)))
	var am: String = equip.get("amulet", {}).get("base", "")
	if am != "":
