		body.add_child(sphere(0.07, G.toon(amc, {"emission": amc, "emission_amount": 0.6, "outline": 0.015}), Vector3(0, 0.62, 0.3)))
	# shoulder pads
	for side in [-1, 1]:
		body.add_child(sphere(0.14, tunic2, Vector3(0.3 * side, 0.68, 0), Vector3(1, 0.7, 1)))
	# scarf
	var sc := Node3D.new()
	sc.position = Vector3(0, 0.78, 0)
	body.add_child(sc)
	sc.add_child(sphere(0.3, scarf, Vector3(0, 0, 0), Vector3(1.1, 0.45, 1.1)))
	var tail := capsule(0.09, 0.5, scarf, Vector3(0, -0.2, -0.4), Vector3(deg_to_rad(60), 0, 0))
	sc.add_child(tail)
	p["scarf"] = tail
	# arms
	for side in [-1, 1]:
		var piv := Node3D.new()
		piv.position = Vector3(0.36 * side, 0.72, 0)
		body.add_child(piv)
