		p["arm%s" % ("L" if side < 0 else "R")] = piv
	# sword in right hand
	var hand := Node3D.new()
	hand.position = Vector3(0, -0.5, 0.05)
	p["armR"].add_child(hand)
	var sw := build_sword(sword_id)
	sw.rotation = Vector3(deg_to_rad(90), 0, 0)
	hand.add_child(sw)
	p["sword"] = sw
	p["hand"] = hand
	# head
	var head := Node3D.new()
	head.position = Vector3(0, 0.98, 0)
	body.add_child(head)
	p["head"] = head
	head.add_child(sphere(0.4, skin, Vector3(0, 0.28, 0), Vector3(1, 0.95, 1), 28))
	# ears
	for side in [-1, 1]:
		head.add_child(sphere(0.07, skin, Vector3(0.38 * side, 0.26, 0)))
	# hair: rounded cartoon cap with soft tufts and a side bang
	head.add_child(sphere(0.44, hair, Vector3(0, 0.5, -0.08), Vector3(1.02, 0.72, 1.02), 28))
	head.add_child(sphere(0.2, hair, Vector3(0.0, 0.74, 0.0), Vector3(1.3, 0.9, 1.1), 14))
	head.add_child(sphere(0.17, hair, Vector3(0.22, 0.7, -0.1), Vector3(1.2, 0.9, 1.0), 14))
	head.add_child(sphere(0.17, hair, Vector3(-0.22, 0.7, -0.1), Vector3(1.2, 0.9, 1.0), 14))
	head.add_child(sphere(0.16, hair, Vector3(0.1, 0.62, 0.3), Vector3(1.6, 0.7, 1.0), 14))  # bang
	head.add_child(sphere(0.12, hair, Vector3(-0.26, 0.58, 0.24), Vector3(1.0, 0.8, 1.2), 12))
	head.add_child(sphere(0.14, hair, Vector3(0.0, 0.4, -0.42), Vector3(1.2, 1.4, 0.9), 12))  # back tuft
	# face (Godot forward is -Z; sprite rotated to look along -Z)
	var f := face("hero_normal", Vector3(0, 0.25, 0.41), 0.58)
	head.add_child(f)
	p["face"] = f
	# hat
	var hat := build_hat(hat_id)
	if hat:
		hat.position = Vector3(0, 0.62, 0)
		head.add_child(hat)
	p["hat"] = hat
	p["root"] = root
	return p

static func build_hat(hat_id: String) -> Node3D:
	if hat_id == "none" or hat_id == "":
		return null
	var n := Node3D.new()
	match hat_id:
		"cap":
			var m := G.toon(Color(0.2, 0.45, 1.0))
			n.add_child(sphere(0.44, m, Vector3(0, 0.0, 0), Vector3(1.0, 0.6, 1.0)))
			n.add_child(box(Vector3(0.5, 0.05, 0.4), m, Vector3(0, -0.05, 0.42)))
			n.add_child(sphere(0.06, G.toon(Color(1, 0.85, 0.2)), Vector3(0, 0.27, 0)))
		"catears":
			var m := G.toon(Color(0.95, 0.75, 0.55))
			var inner := G.toon(Color(1.0, 0.6, 0.7))
			for side in [-1, 1]:
				var ear := cyl(0.0, 0.15, 0.34, m, Vector3(0.28 * side, 0.2, -0.05), Vector3(0, 0, deg_to_rad(-25 * side)))
				n.add_child(ear)
				var inn := cyl(0.0, 0.08, 0.2, inner, Vector3(0.28 * side, 0.2, 0.0), Vector3(0, 0, deg_to_rad(-25 * side)))
				n.add_child(inn)
		"wizard":
			var m := G.toon(Color(0.45, 0.2, 0.8))
			n.add_child(cyl(0.0, 0.42, 0.9, m, Vector3(0.05, 0.35, 0), Vector3(0, 0, deg_to_rad(-12))))
			n.add_child(cyl(0.6, 0.62, 0.06, m, Vector3(0, -0.08, 0)))
			n.add_child(sphere(0.06, G.toon(Color(1, 0.9, 0.3), {"emission": Color(1, 0.9, 0.3), "emission_amount": 0.8}), Vector3(0.2, 0.78, 0)))
		"crown":
			var m := G.toon(Color(1.0, 0.82, 0.2), {"spec": 0.9, "emission": Color(1, 0.8, 0.2), "emission_amount": 0.25, "outline": 0.02})
			n.add_child(cyl(0.3, 0.28, 0.2, m, Vector3(0, 0.0, 0), Vector3.ZERO, 8))
			for i in range(6):
				var a := i * TAU / 6.0
				n.add_child(cyl(0.0, 0.07, 0.2, m, Vector3(cos(a) * 0.27, 0.18, sin(a) * 0.27)))
				n.add_child(sphere(0.045, G.toon(Color(1, 0.3, 0.5)), Vector3(cos(a) * 0.27, 0.27, sin(a) * 0.27)))
	return n

static func build_sword(sword_id: String) -> Node3D:
	# Y axis = blade direction (up), hilt at origin.
	var d: Dictionary = SWORDS.get(sword_id, SWORDS["wood"])
	var n := Node3D.new()
	n.name = "Sword"
	if sword_id == "crown":
		sword_id = "wood"
	var opts := {"rim": 0.5, "spec": 0.9, "spec_size": 0.92}
	if d["glow_amt"] > 0.0:
		opts["emission"] = d["glow"]
		opts["emission_amount"] = d["glow_amt"]
	var blade := G.toon(d["blade"], opts)
	var guard := G.toon(Color(1.0, 0.8, 0.25), {"spec": 0.8})
	var grip := G.toon(Color(0.4, 0.22, 0.12))
	# blade: a flat diamond prism
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var L := 0.95
	var W := 0.085
	var T := 0.022
	var tipL := 0.18
	var verts := [
		Vector3(-W, 0, 0), Vector3(0, 0, T), Vector3(W, 0, 0), Vector3(0, 0, -T),
		Vector3(-W, L - tipL, 0), Vector3(0, L - tipL, T), Vector3(W, L - tipL, 0), Vector3(0, L - tipL, -T),
		Vector3(0, L, 0),
	]
	var tris := [
		[0, 1, 5], [0, 5, 4], [1, 2, 6], [1, 6, 5], [2, 3, 7], [2, 7, 6], [3, 0, 4], [3, 4, 7],
		[4, 5, 8], [5, 6, 8], [6, 7, 8], [7, 4, 8],
		[0, 2, 1], [0, 3, 2],
	]
	var centre := Vector3(0, L * 0.5, 0)
	for tri in tris:
		var a: Vector3 = verts[tri[0]]
		var b: Vector3 = verts[tri[1]]
		var c: Vector3 = verts[tri[2]]
		var nrm := (b - a).cross(c - a).normalized()
		if nrm.dot((a + b + c) / 3.0 - centre) < 0.0:
			var tmp := b
			b = c
			c = tmp
			nrm = -nrm
		for v in [a, c, b]:
			st.set_normal(nrm)
			st.add_vertex(v)
	var mesh := st.commit()
	var bm := mi(mesh, blade, Vector3(0, 0.12, 0))
	n.add_child(bm)
	if sword_id == "rainbow":
		# rainbow stripes on the blade
		var cols := [Color(1, 0.3, 0.3), Color(1, 0.7, 0.2), Color(0.4, 1, 0.4), Color(0.3, 0.6, 1), Color(0.8, 0.4, 1)]
		for i in range(5):
			var s := box(Vector3(0.19, 0.08, 0.06), G.toon(cols[i], {"emission": cols[i], "emission_amount": 0.8, "outline": 0.0}), Vector3(0, 0.3 + i * 0.14, 0))
			n.add_child(s)
	n.add_child(box(Vector3(0.3, 0.06, 0.08), guard, Vector3(0, 0.1, 0)))
	n.add_child(cyl(0.035, 0.035, 0.22, grip, Vector3(0, -0.03, 0)))
	n.add_child(sphere(0.05, guard, Vector3(0, -0.15, 0)))
	n.set_meta("tip", Vector3(0, L + 0.12, 0))
	return n

