				col = Color(1.0, 0.5, 0.75)
			if kind == "king":
				col = Color(0.4, 0.75, 1.0)
			var m := G.unique_toon(col, {"rim": 0.6, "spec": 0.7, "spec_size": 0.9, "shade": 0.6})
			var body := sphere(0.5, m, Vector3(0, 0.42, 0), Vector3(1, 0.85, 1), 24)
