			root.add_child(sphere(0.1, feet, Vector3(0.14, 0.05, 0.08), Vector3(1, 0.6, 1.3)))
			root.add_child(sphere(0.1, feet, Vector3(-0.14, 0.05, 0.08), Vector3(1, 0.6, 1.3)))
			p["mat"] = capm
			p["mat2"] = stem
			p["face"] = face("shroom_normal", Vector3(0, 0.3, 0.31), 0.5)
