			# feet
			root.add_child(sphere(0.2, m, Vector3(0.28, 0.1, 0.05), Vector3(1, 0.6, 1.2), 8))
			root.add_child(sphere(0.2, m, Vector3(-0.28, 0.1, 0.05), Vector3(1, 0.6, 1.2), 8))
			p["face"] = face("rock_normal", Vector3(0, 0.55, 0.52), 0.55)
			p["face_base"] = "rock"
			root.add_child(p["face"])
			p["radius"] = 0.65
			p["height"] = 1.1
	root.scale = Vector3.ONE * d["size"]
	root.rotation.y = PI
	p["root"] = root
