files.shaders/sky_toon.gdshader:
shader_type sky;

// Anime sky: banded gradient, sun with glow, soft puffy cloud bands.
uniform vec3 top_color : source_color = vec3(0.22, 0.45, 0.95);
uniform vec3 mid_color : source_color = vec3(0.45, 0.75, 1.0);
uniform vec3 horizon_color : source_color = vec3(0.92, 0.95, 1.0);
uniform vec3 ground_color : source_color = vec3(0.35, 0.65, 0.95);
uniform float cloud_amount = 0.5;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
	vec2 i = floor(p); vec2 f = fract(p);
	f = f * f * (3.0 - 2.0 * f);
	return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}
float fbm(vec2 p) {
	float v = 0.0; float a = 0.5;
	for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.1; a *= 0.5; }
	return v;
}

void sky() {
	float h = EYEDIR.y;
	vec3 col;
	if (h < 0.0) {
		col = ground_color;
	} else {
		float t1 = smoothstep(0.0, 0.08, h);
		float t2 = smoothstep(0.08, 0.6, h);
		col = mix(horizon_color, mid_color, t1);
		col = mix(col, top_color, t2);
		// clouds projected on a dome
		vec2 uv = EYEDIR.xz / max(h + 0.15, 0.05);
		uv *= 0.9;
		uv.x += TIME * 0.015;
		float n = fbm(uv * 1.2);
		float n2 = fbm(uv * 2.4 + vec2(3.1, 7.7) - TIME * 0.01);
		float c = smoothstep(0.55 - cloud_amount * 0.2, 0.62, n * 0.7 + n2 * 0.4);
		float c_shade = smoothstep(0.6, 0.85, n * 0.7 + n2 * 0.4);
		vec3 cloud = mix(vec3(0.85, 0.88, 1.0), vec3(1.0), c_shade);
		float fade = smoothstep(0.02, 0.25, h);
		col = mix(col, cloud, c * fade);
	}
	// sun
	float sd = max(dot(EYEDIR, LIGHT0_DIRECTION), 0.0);
	col += vec3(1.0, 0.95, 0.8) * (step(0.9985, sd) * 1.5 + pow(sd, 60.0) * 0.5 + pow(sd, 8.0) * 0.12);
	COLOR = col;
}

files.shaders/toon.gdshader:
shader_type spatial;
render_mode cull_back, depth_draw_opaque, specular_schlick_ggx;

// Anime cel shader: 3 light bands, hard rim, hard specular dot, optional texture, flash and emission.
uniform vec4 albedo : source_color = vec4(1.0);
uniform sampler2D tex : source_color, filter_linear_mipmap, repeat_enable;
uniform bool use_tex = false;
uniform bool use_vcol = false;
uniform float uv_scale = 1.0;
uniform float rim_power = 3.0;
uniform float rim_amount = 0.35;
uniform vec4 rim_color : source_color = vec4(1.0, 0.95, 0.85, 1.0);
uniform float spec_amount = 0.25;
uniform float spec_size = 0.95;
uniform vec4 shade_tint : source_color = vec4(0.55, 0.5, 0.75, 1.0);
uniform float shade_level = 0.45;
uniform float mid_level = 0.75;
uniform vec4 emission_color : source_color = vec4(0.0, 0.0, 0.0, 1.0);
uniform float emission_amount = 0.0;
uniform float flash = 0.0;       // 1 = fully white (hit flash)
uniform float wind = 0.0;         // vertex sway for foliage
uniform float alpha = 1.0;

varying vec3 vcol;
varying float vheight;

void vertex() {
	vcol = COLOR.rgb;
	vheight = VERTEX.y;
	if (wind > 0.0) {
		float ph = dot(NODE_POSITION_WORLD.xz, vec2(0.37, 0.61));
		float sway = sin(TIME * 1.7 + ph) * 0.5 + sin(TIME * 2.9 + ph * 1.3) * 0.25;
		VERTEX.x += sway * wind * clamp(VERTEX.y, 0.0, 10.0) * 0.08;
		VERTEX.z += cos(TIME * 1.3 + ph) * wind * clamp(VERTEX.y, 0.0, 10.0) * 0.05;
	}
}

void fragment() {
	vec3 col = albedo.rgb;
	if (use_tex) {
		col *= texture(tex, UV * uv_scale).rgb;
	}
	if (use_vcol) {
		col *= vcol;
	}
	col = mix(col, vec3(1.0), flash);
	ALBEDO = col;
	ROUGHNESS = 0.8;
	METALLIC = 0.0;
	SPECULAR = 0.0;
	float r = 1.0 - clamp(dot(normalize(NORMAL), normalize(VIEW)), 0.0, 1.0);
	float rimv = smoothstep(0.55, 0.62, pow(r, 1.0) );
	EMISSION = emission_color.rgb * emission_amount + rim_color.rgb * rimv * rim_amount * col + vec3(flash) * 0.6;
	ALPHA = alpha * albedo.a;
}

void light() {
	float ndl = dot(normalize(NORMAL), normalize(LIGHT));
	float shadow = ATTENUATION;
	float lit = smoothstep(0.0, 0.04, ndl) * step(0.5, shadow);
	float mid = smoothstep(0.35, 0.40, ndl) * step(0.5, shadow);
	// band levels
	float band = mix(shade_level, mix(mid_level, 1.0, mid), lit);
	vec3 tint = mix(shade_tint.rgb, vec3(1.0), lit);
	DIFFUSE_LIGHT += ALBEDO * LIGHT_COLOR * band * tint / 3.14159;
	vec3 h = normalize(normalize(VIEW) + normalize(LIGHT));
	float s = step(spec_size, dot(normalize(NORMAL), h)) * lit;
	SPECULAR_LIGHT += LIGHT_COLOR * s * spec_amount / 3.14159;
}

files.shaders/post.gdshader:
shader_type canvas_item;

// Full-screen anime post: vignette, slight saturation lift, dash speed lines, dizzy wobble, hit flash.
uniform sampler2D screen_tex : hint_screen_texture, filter_linear;
uniform sampler2D speed_tex : filter_linear;
uniform float speed_amount = 0.0;
uniform float dizzy = 0.0;
uniform float flash = 0.0;
uniform vec4 flash_color : source_color = vec4(1.0, 0.3, 0.4, 1.0);
uniform float vignette = 0.35;
uniform float saturation = 1.12;

void fragment() {
	vec2 uv = SCREEN_UV;
	if (dizzy > 0.0) {
		uv += vec2(sin(uv.y * 20.0 + TIME * 6.0), cos(uv.x * 18.0 + TIME * 5.0)) * 0.006 * dizzy;
	}
	vec3 col = texture(screen_tex, uv).rgb;
	float g = dot(col, vec3(0.299, 0.587, 0.114));
	col = mix(vec3(g), col, saturation);
	vec2 c = uv - 0.5;
	float v = 1.0 - smoothstep(0.35, 0.95, length(c) * 1.3);
	col *= mix(1.0, v, vignette);
	if (speed_amount > 0.0) {
		float sl = texture(speed_tex, uv + vec2(TIME * 0.3, 0.0) * 0.0).a;
		float sl2 = texture(speed_tex, vec2(uv.x, 1.0 - uv.y) + vec2(0.0, TIME * 0.0)).a;
		float m = max(sl, sl2) * smoothstep(0.25, 0.6, length(c));
		col = mix(col, vec3(1.0), m * speed_amount * 0.8);
	}
	col = mix(col, flash_color.rgb, flash * 0.45);
	COLOR = vec4(col, 1.0);
}

files.shaders/grass.gdshader:
shader_type spatial;
render_mode cull_disabled, depth_draw_opaque;

// Stylized grass blades (MultiMesh). Vertex colour from instance; sway; two-tone from root to tip.
uniform vec4 root_color : source_color = vec4(0.25, 0.55, 0.2, 1.0);
uniform vec4 tip_color : source_color = vec4(0.65, 0.9, 0.35, 1.0);
uniform float sway = 1.0;
uniform vec3 player_pos = vec3(0.0, -100.0, 0.0);

varying float vh;
varying float vtint;

void vertex() {
	vh = UV.y; // 1 at tip, 0 at root
	vtint = INSTANCE_CUSTOM.r;
	vec3 wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	float ph = dot(wp.xz, vec2(0.45, 0.35));
	float s = sin(TIME * 2.2 + ph) * 0.35 + sin(TIME * 3.7 + ph * 2.1) * 0.15;
	vec3 off = vec3(s * sway, 0.0, cos(TIME * 1.9 + ph) * 0.2 * sway) * vh * vh;
	// push away from player feet
	vec2 d = wp.xz - player_pos.xz;
	float dist = length(d);
	float push = (1.0 - smoothstep(0.3, 1.3, dist)) * step(abs(wp.y - player_pos.y), 2.0);
	off.xz += normalize(d + vec2(0.001)) * push * 0.6 * vh;
	off.y -= push * 0.4 * vh;
	VERTEX += (inverse(mat3(MODEL_MATRIX)) * off);
}

void fragment() {
	vec3 col = mix(root_color.rgb, tip_color.rgb, vh) * (0.85 + vtint * 0.3);
	ALBEDO = col;
	ROUGHNESS = 1.0;
	SPECULAR = 0.0;
}

void light() {
	float ndl = dot(normalize(NORMAL), normalize(LIGHT));
	float lit = smoothstep(-0.2, 0.1, abs(ndl)) * step(0.5, ATTENUATION);
	float band = mix(0.55, 1.0, lit);
	DIFFUSE_LIGHT += ALBEDO * LIGHT_COLOR * band / 3.14159;
}

files.shaders/outline.gdshader:
shader_type spatial;
render_mode cull_front, unshaded, depth_draw_opaque;

// Inverted-hull anime outline, used as next_pass on toon materials.
uniform float width = 0.025;
uniform vec4 color : source_color = vec4(0.16, 0.08, 0.22, 1.0);
uniform float wind = 0.0;

void vertex() {
	if (wind > 0.0) {
		float ph = dot(NODE_POSITION_WORLD.xz, vec2(0.37, 0.61));
		float sway = sin(TIME * 1.7 + ph) * 0.5 + sin(TIME * 2.9 + ph * 1.3) * 0.25;
		VERTEX.x += sway * wind * clamp(VERTEX.y, 0.0, 10.0) * 0.08;
		VERTEX.z += cos(TIME * 1.3 + ph) * wind * clamp(VERTEX.y, 0.0, 10.0) * 0.05;
	}
	// keep the outline roughly the same thickness on screen regardless of distance (clamped)
	vec4 wp = MODEL_MATRIX * vec4(VERTEX, 1.0);
	float d = length(wp.xyz - CAMERA_POSITION_WORLD);
	float w = width * clamp(d * 0.12, 0.6, 2.2);
	// undo object scale so the extrusion is in world units
	vec3 sc = vec3(length(MODEL_MATRIX[0].xyz), length(MODEL_MATRIX[1].xyz), length(MODEL_MATRIX[2].xyz));
	VERTEX += normalize(NORMAL) * w / max(sc, vec3(0.001));
}

void fragment() {
	ALBEDO = color.rgb;
}

files.shaders/water.gdshader:
shader_type spatial;
render_mode cull_disabled, depth_draw_opaque, unshaded;

// Toon water: two tones, moving highlight bands, foam near shore via depth.
uniform vec4 deep : source_color = vec4(0.1, 0.45, 0.85, 1.0);
uniform vec4 shallow : source_color = vec4(0.35, 0.8, 0.95, 1.0);
uniform vec4 foam : source_color = vec4(1.0, 1.0, 1.0, 1.0);
uniform sampler2D depth_tex : hint_depth_texture;

void vertex() {
	VERTEX.y += sin(VERTEX.x * 0.6 + TIME * 1.2) * 0.08 + cos(VERTEX.z * 0.5 + TIME * 0.9) * 0.08;
}

void fragment() {
	vec2 p = (INV_VIEW_MATRIX * vec4(VERTEX, 1.0)).xz;
	float w1 = sin(p.x * 0.9 + p.y * 0.4 + TIME * 1.1);
	float w2 = sin(p.x * 0.3 - p.y * 1.1 + TIME * 0.7);
	float band = step(0.82, w1 * 0.6 + w2 * 0.5);
	float band2 = step(0.9, sin(p.x * 1.7 + p.y * 1.3 + TIME * 1.6));
	// depth-based shore foam
	float depth_raw = texture(depth_tex, SCREEN_UV).r;
	vec3 ndc = vec3(SCREEN_UV * 2.0 - 1.0, depth_raw);
	vec4 view = INV_PROJECTION_MATRIX * vec4(ndc, 1.0);
	view.xyz /= view.w;
	float scene_depth = -view.z;
	float water_depth = scene_depth - (-VERTEX.z);
	float shore = 1.0 - smoothstep(0.0, 1.2, water_depth);
	float shoreline = step(0.55, shore + 0.25 * sin(p.x * 2.0 + p.y * 1.5 + TIME * 2.0));
	vec3 col = mix(deep.rgb, shallow.rgb, shore);
	col = mix(col, foam.rgb, max(band * 0.6, band2 * 0.8));
	col = mix(col, foam.rgb, shoreline);
	ALBEDO = col;
	ALPHA = 0.9;
}
